1	// The auto-merge policy engine (tasks-dispatch DESIGN §16.11): may THIS diff land
2	// without a person? A task declares `automerge` — `'nothing'`, `'anything'`,
3	// or a list of named diff classes — and this module turns that declaration plus
4	// the branch's actual diff into a verdict. The call is arithmetic over the diff,
5	// never the session's opinion of its own work: a run cannot talk its way past a
6	// text comparison (the narrow-diff posture, generalized).
7	//
8	// THE VOCABULARY IS EXTENSIBLE AS DATA. Built-in diff classes live here; a pack
9	// adds its own by shipping a `merge-rules.json` beside its `pack.mjs` — named
10	// path/kind/edit-shape matchers, validated at load, colliding loudly. A policy
11	// then names any rule, built-in or declared, plus the inline `under:<dir>` scope
12	// that carries its own argument, and an unknown name FAILS CLOSED: a policy this
13	// code cannot fully resolve authorizes nothing.
14	//
15	// A LIST IS A UNION, `&&` IS THE INTERSECTION. Listing two terms widens — each
16	// changed file need only be covered by one of them — so the way to say "docs,
17	// but only under this folder" is one `&&` term, never two list entries.
18	//
19	// POLICY SEMANTICS, in evaluation order:
20	//   - `'nothing'`  — never mergeable. `'anything'` — mergeable (the repo's own
21	//     delivery settings still apply downstream, land-pr.mjs).
22	//   - a LIST mixes allow terms and `reject:<name>` terms. A reject matching any
23	//     changed file vetoes the whole diff; otherwise every changed file must be
24	//     covered by some allow term (first listed match wins), and every matched
25	//     rule's whole-diff constraint (e.g. "one code directory") must hold. A list
26	//     with no allow term is an authoring error, not "anything except" — spell
27	//     that as `['anything', 'reject:<name>']`.
28	//   - THE SELF-WIDENING GUARD: under a list policy, a change to the files that
29	//     define policies (`merge-rules.json`, `tasks/<name>/task.mjs`, this module,
30	//     its work-scope gate) is never coverable unless it is comment-only — a run
31	//     must not be able to grant itself a wider authorization than it started
32	//     with. Only the plain `'anything'` (the trusted lane: the vendored-mount
33	//     converge) can land such a change.
34	//
35	// Two judging surfaces read one resolution path: the landing lane's CLI below
36	// (what the worker doc tells a run to execute before it may merge), and the
37	// `automerge-policy-scope` work check beside this file, which re-evaluates the
38	// same verdict over a branch that stamped the arming trailer.
39	
40	import path from 'node:path';
41	import { readFileSync, existsSync } from 'node:fs';
42	import { execFileSync } from 'node:child_process';
43	import { COMMENT_CHECKABLE, commentOnly } from '../../engine/checks/helpers/code-scanning.mjs';
44	import { FILE_CLASSES } from '../../engine/checks/helpers/pattern-rules.mjs';
45	import { isActive } from '../../engine/pack_loader/pack-registry.mjs';
46	
47	export { COMMENT_CHECKABLE, commentOnly };
48	
49	export const POLICY_NOTHING = 'nothing';
50	export const POLICY_ANYTHING = 'anything';
51	
52	// The commit-message trailer a run stamps when it intends to land its own PR
53	// under a granular policy — what makes the work-scope gate self-gating: no
54	// trailer, no armed auto-merge, nothing to judge. The policy expression is the
55	// string form below (`a;b;reject:c`).
56	export const AUTOMERGE_TRAILER = 'Claudinite-Automerge-Policy';
57	export const AUTOMERGE_TRAILER_RE = /^Claudinite-Automerge-Policy:[ \t]*(\S+)[ \t]*$/m;
58	
59	// --- path classification (shared with narrow-diff.mjs, which re-exports it) ---
60	
61	const DOC_EXTENSIONS = new Set(['.md', '.markdown', '.txt', '.rst']);
62	
63	const TEST_DIRS = new Set(['test', 'tests', '__tests__', 'spec', 'specs', 'fixtures', 'testdata']);
64	
65	// A path's kind, from the path alone: 'doc', 'test', or 'code'. Directory names
66	// are matched on whole segments (`tests/`), never on substrings, so `latest/` is
67	// not a test directory; file names are matched on the conventions every ecosystem
68	// here shares.
69	export function classifyPath(file) {
70	  const segments = file.split('/');
71	  const name = segments[segments.length - 1];
72	  if (segments.slice(0, -1).some((seg) => TEST_DIRS.has(seg) || seg.endsWith('-tests') || seg.endsWith('_tests'))) return 'test';
73	  if (/(^|[.\-_])(test|tests|spec)[.\-_]/i.test(name) || /^test_/i.test(name)) return 'test';
74	  if (DOC_EXTENSIONS.has(path.extname(name).toLowerCase())) return 'doc';
75	  return 'code';
76	}
77	
78	// --- diff entries -------------------------------------------------------------
79	
80	// One changed file with both contents: null `before` = added, null `after` =
81	// deleted. Everything below judges these, so a caller with another diff source
82	// (the work-scope context) builds the same shape.
83	export const changeKindOf = ({ before, after }) =>
84	  (before == null ? 'added' : after == null ? 'deleted' : 'modified');
85	
86	// Only line removals (and nothing else): the after-lines are an ordered
87	// subsequence of the before-lines. Deliberately order-preserving — a reorder is
88	// an edit, not a removal — and a whole-file deletion is every line removed.
89	export function removalsOnly(before, after) {
90	  return shrinkOnly(before, after, (line, original) => line === original);
91	}
92	
93	// Removals, plus in-line TRIMS: every surviving line either equals a line it
94	// replaces or is a character-subsequence of one — a line cut in half, a word
95	// struck from its middle, a truncation closed with a period the original
96	// already held. What can never pass is growth: no new line, and no character a
97	// replaced line did not already carry in order. The alignment is greedy and
98	// backtrack-free, so a pathological reshuffle can read as not-a-trim — that
99	// end fails safe (the diff parks for review).
100	export function trimsOnly(before, after) {
101	  return shrinkOnly(before, after, isCharSubsequence);
102	}
103	
104	function shrinkOnly(before, after, lineSatisfies) {
105	  if (after == null) return true;
106	  if (before == null) return false;
107	  const from = before.split('\n');
108	  const to = after.split('\n');
109	  let i = 0;
110	  for (const line of to) {
111	    while (i < from.length && !lineSatisfies(line, from[i])) i += 1;
112	    if (i === from.length) return false;
113	    i += 1;
114	  }
115	  return true;
116	}
117	
118	function isCharSubsequence(needle, hay) {
119	  let i = 0;
120	  for (const c of needle) {
121	    i = hay.indexOf(c, i);
122	    if (i === -1) return false;
123	    i += 1;
124	  }
125	  return true;
126	}
127	
128	const isCommentOnlyChange = (e) => changeKindOf(e) === 'modified' && commentOnly(e.file, e.before, e.after);
129	
130	// --- the rule registry --------------------------------------------------------
131	// A rule is `{ name, appliesTo(entry) }` plus, for the whole-diff rules, a
132	// `constraint(coveredEntries)` returning null or the reason it fails. `appliesTo`
133	// answers both roles a policy can use the name in: as an allow term it covers the
134	// files it applies to, as a `reject:` term it vetoes on them.
135	
136	// The two code-locality rules deliberately do NOT apply to a comment-only code
137	// file (mirroring narrowVerdict): a comment edit is `comment-only-changes`'
138	// business, and counting it toward the file/directory budget would fail a diff
139	// the policy's author plainly meant to allow.
140	const isRealCodeChange = (e) => classifyPath(e.file) === 'code' && !isCommentOnlyChange(e);
141	
142	export const BUILTIN_MERGE_RULES = new Map([
143	  ['doc-changes', {
144	    appliesTo: (e) => changeKindOf(e) !== 'deleted' && classifyPath(e.file) === 'doc',
145	  }],
146	  ['readme-changes', {
147	    appliesTo: (e) => changeKindOf(e) !== 'deleted' && path.basename(e.file).toLowerCase() === 'readme.md',
148	  }],
149	  ['comment-only-changes', {
150	    appliesTo: isCommentOnlyChange,
151	  }],
152	  ['test-changes', {
153	    appliesTo: (e) => changeKindOf(e) !== 'deleted' && classifyPath(e.file) === 'test',
154	  }],
155	  ['markdown-line-removals', {
156	    appliesTo: (e) => e.file.toLowerCase().endsWith('.md')
157	      && changeKindOf(e) !== 'added' && removalsOnly(e.before, e.after),
158	  }],
159	  // The trim superset of the rule above: whole-line removals plus in-line trims
160	  // (trimsOnly) — for a prune allowed to cut a line down, never to grow one.
161	  ['markdown-trims', {
162	    appliesTo: (e) => e.file.toLowerCase().endsWith('.md')
163	      && changeKindOf(e) !== 'added' && trimsOnly(e.before, e.after),
164	  }],
165	  ['file-additions', {
166	    appliesTo: (e) => changeKindOf(e) === 'added',
167	  }],
168	  ['generated-file-changes', {
169	    appliesTo: (e) => changeKindOf(e) !== 'deleted' && path.basename(e.file).includes('GENERATED'),
170	  }],
171	  // The language-scoped class, matching ANY change to a JavaScript-family file —
172	  // built in mostly for its `reject:` use ("nothing may touch the JS"), which is
173	  // why it applies to every change kind. Its file set is the checks engine's own
174	  // JavaScript class, so the two surfaces cannot disagree on what counts.
175	  ['javascript-changes', {
176	    appliesTo: (e) => FILE_CLASSES.javascriptFiles.test(e.file),
177	  }],
178	  ['single-file-code-changes', {
179	    appliesTo: isRealCodeChange,
180	    constraint: (covered) => {
181	      const files = [...new Set(covered.map((e) => e.file))].sort();
182	      return files.length <= 1 ? null : `code changed in ${files.length} files: ${files.join(', ')}`;
183	    },
184	  }],
185	  ['single-folder-code-changes', {
186	    appliesTo: isRealCodeChange,
187	    constraint: (covered) => {
188	      const dirs = [...new Set(covered.map((e) => path.dirname(e.file)))].sort();
189	      return dirs.length <= 1 ? null : `code changed in ${dirs.length} directories: ${dirs.join(', ')}`;
190	    },
191	  }],
192	]);
193	
194	// Composites expand into their member allow terms — `narrow-diff` is the queue's
195	// historical `Merge: if-narrow` shape. Slightly stricter than the retired
196	// narrowVerdict on purpose: a DELETED doc or test file is no longer silently
197	// allowed (deciding a document should not exist is a reviewed change — the
198	// improve-comments-scope lesson), which fails toward a parked PR, never a merge.
199	export const COMPOSITE_POLICIES = new Map([
200	  ['narrow-diff', ['doc-changes', 'test-changes', 'comment-only-changes', 'single-folder-code-changes']],
201	]);
202	
203	// --- the inline path scope (`under:<dir>`) ------------------------------------
204	
205	// A rule name that carries its own argument: `under:packs/claudinite-tasks`
206	// covers every change inside that directory. It exists because a scope is
207	// usually per-request — the one folder an ad-hoc ask or a task is confined to —
208	// where a named merge-rules.json rule is per-pack and costs a commit to add.
209	//
210	// It covers any change KIND inside the directory (added, modified, deleted):
211	// "any change under this folder" reads as literally any. And it scopes rather
212	// than widens — a changed file outside the folder is covered by no allow term,
213	// so a diff that strays parks — with POLICY_SOURCES below still absolute, so a
214	// folder scope cannot reach the files that define policies even when they sit
215	// inside it.
216	export const UNDER_PREFIX = 'under:';
217	
218	const PATH_SEGMENT_RE = /^[A-Za-z0-9._-]+$/;
219	
220	// The rule an `under:<dir>` term denotes, or null when `<dir>` is not a usable
221	// repo-relative directory (absolute, empty, or carrying a `.`/`..` segment).
222	// Null is a verdict: an unresolvable scope makes the whole policy invalid, which
223	// authorizes nothing — the same fail-closed answer an unknown rule name gets.
224	export function underRule(term) {
225	  const dir = term.slice(UNDER_PREFIX.length).replace(/\/+$/, '');
226	  const segments = dir.split('/');
227	  if (!dir || segments.some((seg) => !PATH_SEGMENT_RE.test(seg) || seg === '.' || seg === '..')) return null;
228	  const prefix = `${dir}/`;
229	  return { name: term, appliesTo: (e) => e.file.startsWith(prefix) };
230	}
231	
232	// --- the `&&` intersection ----------------------------------------------------
233	
234	// A policy list is a UNION: adding a term widens what may land. `&&` is the one
235	// narrowing operator — `under:product-wiki&&doc-changes` covers a file only when
236	// every part covers it, so it reads as "docs, and only under that folder".
237	//
238	// Whitespace around it is accepted wherever a human writes one (an issue's
239	// `Automerge:` line, a task declaration) and canonicalized away by
240	// `policyExpression`, so what rides the commit trailer stays one whitespace-free
241	// token. `&` is not a legal character in a rule name or an `under:` path, so the
242	// operator can never be read as part of a term.
243	export const CONJUNCTION = '&&';
244	
245	const conjunctionParts = (term) => term.split(CONJUNCTION).map((p) => p.trim());
246	
247	// --- pack-declared rules (merge-rules.json) -----------------------------------
248	
249	export const MERGE_RULES_FILE = 'merge-rules.json';
250	
251	const RULE_NAME_RE = /^[a-z0-9]+(-[a-z0-9]+)*$/;
252	const DECLARED_KEYS = ['name', 'pathMatching', 'excludePathMatching', 'changeKinds', 'editShape', 'coversMountPolicySources'];
253	const CHANGE_KINDS = ['added', 'modified', 'deleted'];
254	const EDIT_SHAPES = ['any', 'removals-only', 'comment-only'];
255	
256	// Regex-as-string in the `/body/flags` form declared-checks.json already uses —
257	// the same inline parse pattern-rules.mjs applies (this module cannot import the
258	// checks engine's private compiler, so the six lines live here and point there).
259	function compileRegex(raw, where) {
260	  const m = /^\/(.*)\/([a-z]*)$/s.exec(String(raw));
261	  if (!m) throw new Error(`${where}: ${JSON.stringify(raw)} is not a /pattern/ regex string`);
262	  return new RegExp(m[1], m[2]);
263	}
264	
265	// One declared rule compiled into the registry shape. Every key is validated and
266	// `changeKinds`/`editShape` are REQUIRED — a matcher whose reach is defaulted is
267	// a matcher nobody decided (the corpus' explicit-over-default rule).
268	export function compileDeclaredRule(spec, where) {
269	  if (spec === null || typeof spec !== 'object' || Array.isArray(spec)) {
270	    throw new Error(`${where}: a merge rule is an object, not ${JSON.stringify(spec)}`);
271	  }
272	  for (const key of Object.keys(spec)) {
273	    if (!DECLARED_KEYS.includes(key)) {
274	      throw new Error(`${where}: "${key}" is not a merge-rule key — the vocabulary is: ${DECLARED_KEYS.join(', ')}`);
275	    }
276	  }
277	  if (typeof spec.name !== 'string' || !RULE_NAME_RE.test(spec.name)) {
278	    throw new Error(`${where}: a merge rule needs a kebab-case "name"`);
279	  }
280	  const pathMatching = compileRegex(spec.pathMatching, `${where} (${spec.name}).pathMatching`);
281	  const exclude = spec.excludePathMatching === undefined
282	    ? null : compileRegex(spec.excludePathMatching, `${where} (${spec.name}).excludePathMatching`);
283	  if (!Array.isArray(spec.changeKinds) || !spec.changeKinds.length
284	      || spec.changeKinds.some((k) => !CHANGE_KINDS.includes(k))) {
285	    throw new Error(`${where} (${spec.name}): "changeKinds" is a non-empty subset of ${CHANGE_KINDS.join(', ')}`);
286	  }
287	  if (!EDIT_SHAPES.includes(spec.editShape)) {
288	    throw new Error(`${where} (${spec.name}): "editShape" must be one of ${EDIT_SHAPES.join(', ')} — declared, never defaulted`);
289	  }
290	  // The one key that may relax the self-widening guard, and only for files under
291	  // the VENDORED MOUNT (see POLICY_SOURCES below): declaring it is an owner
292	  // saying "this task may rewrite the mount, policy definitions included" — the
293	  // adoption/converge grant. `true` only, so it cannot be half-declared.
294	  if (spec.coversMountPolicySources !== undefined && spec.coversMountPolicySources !== true) {
295	    throw new Error(`${where} (${spec.name}): "coversMountPolicySources" takes only \`true\` — omit it otherwise`);
296	  }
297	  return {
298	    name: spec.name,
299	    coversMountPolicySources: spec.coversMountPolicySources === true,
300	    appliesTo(e) {
301	      if (!pathMatching.test(e.file) || (exclude && exclude.test(e.file))) return false;
302	      if (!spec.changeKinds.includes(changeKindOf(e))) return false;
303	      if (spec.editShape === 'removals-only') return changeKindOf(e) !== 'added' && removalsOnly(e.before, e.after);
304	      if (spec.editShape === 'comment-only') return isCommentOnlyChange(e);
305	      return true;
306	    },
307	  };
308	}
309	
310	// The merge rules the ACTIVE packs declare, keyed by name. `packs` are discovered
311	// pack objects (each with `.dir`), `config` the normalized repo config — the pair
312	// both judging surfaces already hold. A broken declaration or a name collision is
313	// an ERROR entry, never a silent drop: a policy naming the broken rule must fail
314	// closed, and the error text is what gets it fixed.
315	export function declaredMergeRules(packs, config) {
316	  const rules = new Map();
317	  const errors = [];
318	  for (const pack of (packs ?? []).filter((p) => p.dir && isActive(p, config))) {
319	    const file = path.join(pack.dir, MERGE_RULES_FILE);
320	    if (!existsSync(file)) continue;
321	    const where = `${pack.id}/${MERGE_RULES_FILE}`;
322	    let specs;
323	    try {
324	      specs = JSON.parse(readFileSync(file, 'utf8'));
325	      if (!Array.isArray(specs)) throw new Error('the file must hold an array of rule objects');
326	    } catch (e) {
327	      errors.push(`${where}: ${e.message}`);
328	      continue;
329	    }
330	    for (const spec of specs) {
331	      try {
332	        const rule = compileDeclaredRule(spec, where);
333	        if (BUILTIN_MERGE_RULES.has(rule.name) || COMPOSITE_POLICIES.has(rule.name) || rules.has(rule.name)) {
334	          throw new Error(`rule name "${rule.name}" is already taken — merge-rule names are one flat namespace`);
335	        }
336	        rules.set(rule.name, rule);
337	      } catch (e) {
338	        errors.push(e.message.startsWith(where) ? e.message : `${where}: ${e.message}`);
339	      }
340	    }
341	  }
342	  return { rules, errors };
343	}
344	
345	// --- policy parsing -----------------------------------------------------------
346	
347	const TERM_NAME_RE = /^(under:\S+|[a-z0-9]+(-[a-z0-9]+)*)$/;
348	
349	// A policy, normalized from any surface it rides — the declaration's string or
350	// array, the item's `Merge:` field, the commit trailer's `a;b;reject:c` — into
351	// { kind: 'nothing' | 'anything' } or { kind: 'rules', allow, reject } or
352	// { kind: 'invalid', reason }. Invalid is a verdict-shaped answer on purpose:
353	// every consumer treats it as "authorizes nothing", loudly.
354	export function normalizePolicy(raw) {
355	  if (raw == null) return { kind: POLICY_NOTHING };
356	  const terms = Array.isArray(raw)
357	    ? raw.map((t) => String(t).trim())
358	    : String(raw).trim().split(';').map((t) => t.trim());
359	  if (terms.length === 1) {
360	    const one = terms[0].toLowerCase();
361	    if (one === POLICY_NOTHING || one === '') return { kind: POLICY_NOTHING };
362	    if (one === POLICY_ANYTHING) return { kind: POLICY_ANYTHING };
363	    // The queue's historical spellings for its one pre-policy authorization.
364	    if (one === 'if-narrow' || one === 'yes' || one === 'true') return normalizePolicy(['narrow-diff']);
365	  }
366	  const allow = [];
367	  const reject = [];
368	  for (const term of terms) {
369	    const isReject = term.startsWith('reject:');
370	    const parts = conjunctionParts(isReject ? term.slice('reject:'.length) : term);
371	    for (const part of parts) {
372	      if (!TERM_NAME_RE.test(part)) {
373	        return { kind: 'invalid', reason: `"${term}" is not a policy term (rule names or under:<dir>, joined with && and optionally reject:-prefixed)` };
374	      }
375	      if (part.startsWith(UNDER_PREFIX) && !underRule(part)) {
376	        return { kind: 'invalid', reason: `"${part}" names no usable repo-relative directory — spell it under:packs/some-pack` };
377	      }
378	    }
379	    // A composite is itself a union, so intersecting one is ambiguous, and the
380	    // whole-policy words mean nothing narrowed: both are authoring errors.
381	    if (parts.length > 1) {
382	      const notIntersectable = parts.find((p) => COMPOSITE_POLICIES.has(p) || p === POLICY_ANYTHING || p === POLICY_NOTHING);
383	      if (notIntersectable) {
384	        return { kind: 'invalid', reason: `"${notIntersectable}" cannot sit in an && term — intersect specific rules` };
385	      }
386	    }
387	    const name = parts.join(CONJUNCTION);
388	    if (isReject) {
389	      if (COMPOSITE_POLICIES.has(name)) return { kind: 'invalid', reason: `"${term}" rejects a composite — name the specific rules to reject` };
390	      reject.push(name);
391	    } else if (name === POLICY_ANYTHING) {
392	      allow.push(name);
393	    } else if (name === POLICY_NOTHING) {
394	      return { kind: 'invalid', reason: `"nothing" cannot sit in a rule list — it is a whole policy of its own` };
395	    } else {
396	      allow.push(...(COMPOSITE_POLICIES.get(name) ?? [name]));
397	    }
398	  }
399	  if (!allow.length) {
400	    return { kind: 'invalid', reason: 'the policy lists no allow term — "anything except X" is spelled ["anything", "reject:X"]' };
401	  }
402	  return { kind: 'rules', allow: [...new Set(allow)], reject: [...new Set(reject)] };
403	}
404	
405	// The string form of a declared policy — what rides the commit trailer and the
406	// worker's CLI invocation. Inverse of normalizePolicy for every legal value, and
407	// the one place whitespace around `&&` is collapsed, which is what keeps the
408	// stamped trailer a single whitespace-free token.
409	export const policyExpression = (policy) =>
410	  (Array.isArray(policy) ? policy : String(policy ?? POLICY_NOTHING).split(';'))
411	    .map((t) => conjunctionParts(String(t).trim()).join(CONJUNCTION))
412	    .join(';');
413	
414	// --- the verdict --------------------------------------------------------------
415	
416	// The files no granular policy may cover except as comment-only edits: the
417	// sources the policy machinery itself is read from. Whatever an allow rule says,
418	// a run authorized by a list must not be able to rewrite what it is authorized
419	// to do. (`'anything'` — the vendored-converge lane — is deliberately exempt:
420	// the mount refresh replaces these files wholesale, and that lane's trust is the
421	// repo's delivery setting, not a diff class.)
422	//
423	// One narrow relaxation: such a file UNDER THE VENDORED MOUNT may be covered by
424	// a declared rule carrying `coversMountPolicySources` — the shape an adoption
425	// re-vendor has, where policy files arrive canon-authored inside the pack trees
426	// it copies. The flag rides merge-rules.json, which is itself guarded and
427	// owner-committed, so a run cannot grant it to itself; repo-owned policy
428	// sources (everything outside the mount) stay absolute.
429	const POLICY_SOURCES = /(^|\/)(merge-rules\.json|merge-policy\.mjs|workRules\/automerge-policy-scope\.mjs|tasks\/[^/]+\/task\.mjs)$/;
430	const VENDORED_MOUNT = /^\.claudinite\/shared\//;
431	
432	// The whole verdict over a diff. `entries` are `{ file, before, after }` (null
433	// side = added/deleted); `declaredRules` a Map from declaredMergeRules, with its
434	// `errors` passed through so a broken declaration fails any policy that names
435	// the broken pack's rule set. Returns { mergeable, why, files, problems }:
436	// `files` carries one line per changed file (its covering rule, or its
437	// violation), `problems` each refusal as { file, what } — file null for a
438	// whole-diff refusal — because a run that parks has to say what it parked over.
439	export function policyVerdict({ policy, entries, declaredRules = new Map(), ruleErrors = [] }) {
440	  const refuse = (problems, files = []) => ({
441	    mergeable: false, why: problems.map((p) => p.what).join('; '), files, problems,
442	  });
443	  const norm = normalizePolicy(policy);
444	  if (norm.kind === 'invalid') return refuse([{ file: null, what: `invalid policy: ${norm.reason}` }]);
445	  if (norm.kind === POLICY_NOTHING) {
446	    return refuse([{ file: null, what: 'the policy authorizes nothing to auto-merge' }]);
447	  }
448	  if (norm.kind === POLICY_ANYTHING) {
449	    return { mergeable: true, why: 'the policy authorizes any diff (the repo\'s delivery settings still apply)', files: [], problems: [] };
450	  }
451	  if (!entries.length) {
452	    return refuse([{ file: null, what: 'this branch changes nothing against the base — there is nothing to merge' }]);
453	  }
454	
455	  const resolveOne = (name) => (name.startsWith(UNDER_PREFIX)
456	    ? underRule(name)
457	    : BUILTIN_MERGE_RULES.get(name) ?? declaredRules.get(name) ?? null);
458	  // An `&&` term is one rule that every part must agree on — for coverage and
459	  // for the whole-diff constraints alike. It deliberately carries no
460	  // `coversMountPolicySources`: that grant belongs to the declared rule that was
461	  // committed with it, never to an expression composed around it.
462	  const resolve = (name) => {
463	    if (!name.includes(CONJUNCTION)) return resolveOne(name);
464	    const parts = name.split(CONJUNCTION).map(resolveOne);
465	    if (parts.some((r) => !r)) return null;
466	    return {
467	      name,
468	      appliesTo: (e) => parts.every((r) => r.appliesTo(e)),
469	      constraint: (covered) => parts.map((r) => r.constraint?.(covered) ?? null).find(Boolean) ?? null,
470	    };
471	  };
472	  const unknown = [...norm.allow, ...norm.reject].filter((n) => n !== POLICY_ANYTHING && !resolve(n));
473	  if (unknown.length) {
474	    const errs = ruleErrors.length ? ` (rule declarations also failed to load: ${ruleErrors.join('; ')})` : '';
475	    return refuse([{ file: null, what: `unresolved rule name(s): ${unknown.join(', ')} — an unknown rule authorizes nothing${errs}` }]);
476	  }
477	
478	  const files = [];
479	  const problems = [];
480	  const coveredBy = new Map(); // allow name -> entries it covered
481	  for (const entry of entries) {
482	    const { file } = entry;
483	    if (POLICY_SOURCES.test(file) && !isCommentOnlyChange(entry)) {
484	      const mountCoverer = VENDORED_MOUNT.test(file)
485	        && norm.allow.find((n) => resolve(n)?.coversMountPolicySources && resolve(n).appliesTo(entry));
486	      if (!mountCoverer) {
487	        files.push({ file, verdict: 'policy-source' });
488	        problems.push({ file, what: `${file} defines auto-merge policy itself — no granular policy may change it` });
489	        continue;
490	      }
491	      // Exempted: it falls through to the ordinary reject/coverage flow below,
492	      // so a reject term still vetoes it and the flagged rule still has to
493	      // cover it on its own terms.
494	    }
495	    const rejectedBy = norm.reject.find((n) => resolve(n).appliesTo(entry));
496	    if (rejectedBy) {
497	      files.push({ file, verdict: `rejected:${rejectedBy}` });
498	      problems.push({ file, what: `${file} matches reject:${rejectedBy}` });
499	      continue;
500	    }
501	    const coverer = norm.allow.find((n) => n === POLICY_ANYTHING || resolve(n).appliesTo(entry));
502	    if (coverer === undefined) {
503	      files.push({ file, verdict: 'uncovered' });
504	      problems.push({ file, what: `${file} (${changeKindOf(entry)} ${classifyPath(entry.file)}) is covered by no allow term` });
505	      continue;
506	    }
507	    files.push({ file, verdict: `covered:${coverer}` });
508	    if (!coveredBy.has(coverer)) coveredBy.set(coverer, []);
509	    coveredBy.get(coverer).push(entry);
510	  }
511	  for (const [name, covered] of coveredBy) {
512	    const failed = resolve(name)?.constraint?.(covered) ?? null;
513	    if (failed) problems.push({ file: null, what: `${name}: ${failed}` });
514	  }
515	
516	  return problems.length
517	    ? refuse(problems, files)
518	    : { mergeable: true, why: `every changed file is covered (${[...coveredBy.keys()].join(', ')})`, files, problems: [] };
519	}
520	
521	// --- the diff against a base ref (shared with narrow-diff.mjs) ----------------
522	
523	// `stderr: ignore` because the ONE expected failure here — `git show` on a path
524	// that does not exist at that ref — is how an added or deleted file answers, and
525	// letting git narrate it once per such file buries the verdict the caller reads.
526	const git = (args, cwd) => execFileSync('git', args, {
527	  cwd, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024, stdio: ['ignore', 'pipe', 'ignore'],
528	});
529	
530	// The content of `file` at `ref`, or null when it does not exist there (an added
531	// file) — the same answer a deleted file's "after" gets.
532	function contentAt(ref, file, cwd) {
533	  try {
534	    return git(['show', `${ref}:${file}`], cwd);
535	  } catch {
536	    return null;
537	  }
538	}
539	
540	// The diff this branch carries against `base`, read from the merge base so
541	// commits that landed on the base meanwhile are not counted as this run's work.
542	export function diffEntries({ base, cwd = process.cwd() }) {
543	  // The checkouts these runs work in are shallow, where `merge-base` has no common
544	  // ancestor to find; the base ref itself is then the honest comparison point.
545	  let mergeBase;
546	  try {
547	    mergeBase = git(['merge-base', base, 'HEAD'], cwd).trim();
548	  } catch {
549	    mergeBase = base;
550	  }
551	  const names = git(['diff', '--name-only', mergeBase, 'HEAD'], cwd).split('\n').map((l) => l.trim()).filter(Boolean);
552	  return names.map((file) => ({
553	    file,
554	    before: contentAt(mergeBase, file, cwd),
555	    after: contentAt('HEAD', file, cwd),
556	  }));
557	}
558	
559	// --- the CLI ------------------------------------------------------------------
560	// What the landing lane runs before it may merge:
561	//   node <this file> --base origin/main --policy 'comment-only-changes;readme-changes'
562	// Prints one line per changed file and a final `AUTOMERGE: yes|no — why` verdict
563	// line the worker quotes. Pack-declared rules resolve from the repo's ACTIVE
564	// packs (loaded here, not at import time — discovery re-importing this module
565	// mid-evaluation must find no work started).
566	async function main() {
567	  const argv = process.argv.slice(2);
568	  const at = (flag) => (argv.includes(flag) ? argv[argv.indexOf(flag) + 1] : null);
569	  const cwd = at('--root') ?? process.env.CLAUDE_PROJECT_DIR ?? process.cwd();
570	  const base = at('--base') ?? 'origin/main';
571	  const policy = at('--policy');
572	  if (policy === null) {
573	    console.error('merge-policy: --policy is required (the task\'s automerge, or the item\'s Merge: value)');
574	    process.exitCode = 2;
575	    return;
576	  }
577	
578	  const { loadPacks } = await import('../../engine/pack_loader/pack-registry.mjs');
579	  const { loadConfig } = await import('../../engine/checks/helpers/repo-context.mjs');
580	  const packs = await loadPacks({ localRoot: cwd });
581	  const { rules, errors } = declaredMergeRules(packs, loadConfig(cwd));
582	  for (const e of errors) console.error(`merge-policy: ${e}`);
583	
584	  const entries = diffEntries({ base, cwd });
585	  const verdict = policyVerdict({ policy, entries, declaredRules: rules, ruleErrors: errors });
586	  for (const { file, verdict: v } of verdict.files) console.log(`  ${v.padEnd(32)} ${file}`);
587	  console.log(`\nAUTOMERGE: ${verdict.mergeable ? 'yes' : 'no'} — ${verdict.why}`);
588	}
589	
590	if (import.meta.url === `file://${process.argv[1]}`) {
591	  main().catch((e) => { console.error(`merge-policy: ${e.message}`); process.exitCode = 1; });
592	}
