// The task declaration contract (per-project-scheduling DESIGN §1) — the single
// source of truth for what a `tasks/<name>/task.mjs` default export must carry.
// Both the author-time `task-declaration-shape` check and the executor-side
// `validate-dispatch` validate against this one function, so the accepted shape
// can never drift between the two surfaces.

import { ACCEPTED_FREQUENCIES, normalizeFrequency } from './calendar.mjs';
import { MODEL_FAMILIES } from './model-map.mjs';
import { EXECUTING_LEASH_MS } from './queue/leases.mjs';
import { normalizePolicy } from './merge-policy.mjs';

// A declared timeout is always a whole number of seconds, > 0.
const isPositiveInt = (n) => Number.isInteger(n) && n > 0;

// A code-work command must stay inside its own task directory — no absolute
// path and no `..` traversal in the command string — the same containment the
// worker-file rule gives agent_instructions (task-code-work DESIGN §2).
const escapesTaskDir = (cmd) => /(^|\s)\//.test(cmd) || cmd.includes('..');

// Task execution is two similar, consecutive phases — deterministic CODE-WORK,
// then AGENTIC WORK — and the field names say so. Neither phase is named for
// the other: the code phase is not preparation for the agent, it is the first
// of two peers, and a task may declare only it.
//
// Two renames have reached these fields (2026-08-06 agent_preprocessing →
// prework, 2026-08-18 prework → code-work); both legacy spellings stay accepted
// here, since a consumer's own local packs rename on their own clock. Every
// legacy key maps straight to today's canonical name rather than to its
// immediate successor, so a declaration written for the oldest vocabulary
// normalizes in one pass. Canonical names win when both are present.
const LEGACY_FIELDS = {
  agent_preprocessing: 'code_work',
  agent_preprocessing_timeout: 'code_work_timeout',
  prework: 'code_work',
  prework_timeout: 'code_work_timeout',
  after: 'schedule_after',
};

// Return the declaration with canonical field names. Non-objects pass through
// untouched so validateTaskDeclaration still reports them. Loaders (discover,
// resolve-dispatch) normalize once; everything downstream sees only `code_work`.
export function normalizeTaskDeclaration(decl) {
  if (decl === null || typeof decl !== 'object' || Array.isArray(decl)) return decl;
  const out = { ...decl };
  for (const [legacy, canonical] of Object.entries(LEGACY_FIELDS)) {
    if (out[legacy] !== undefined) {
      if (out[canonical] === undefined) out[canonical] = out[legacy];
      delete out[legacy];
    }
  }
  // THE ONE DOOR for the retired frequency spellings (DESIGN §17.1). Here rather than in the
  // calendar because a frequency is read by more than the calendar — see `normalizeFrequency`.
  if (out.frequency !== undefined) out.frequency = normalizeFrequency(out.frequency);
  // The retired outcome ceilings become the outcome/policy pair. An explicit
  // `automerge` beside a legacy spelling wins: a half-migrated declaration
  // keeps the narrower intent it states.
  if (LEGACY_OUTCOMES[out.expected_outcome] !== undefined) {
    if (out.automerge === undefined) out.automerge = LEGACY_OUTCOMES[out.expected_outcome];
    out.expected_outcome = 'pr';
  }
  return out;
}

// The write ceiling a task declares (DESIGN §1, §4). A declared MAXIMUM, not a
// promise: `none` may never open a PR; `pr` may open one, and what (if anything)
// the run may then MERGE is the separate `automerge` policy — 'nothing',
// 'anything', or a list of diff classes merge-policy.mjs evaluates the actual
// diff against. "No change" is always legal.
export const OUTCOMES = ['none', 'pr'];

// The retired one-word ceilings, each carrying the policy it always meant. They
// stay accepted forever — a member's own task files rename on their own clock —
// and normalize at the door like the code-work renames: `open-pr` is a pr task
// that merges nothing, `merged-pr` a pr task authorized for anything.
export const LEGACY_OUTCOMES = { 'open-pr': 'nothing', 'merged-pr': 'anything' };


// The retired scope vocabulary. It routed a slot dispatch to one of two labels, and
// its last reader went with the slot scheduler (#974): reach is now a property of
// which endpoint the hand-off calls (`invocation_endpoint`), so nothing anywhere
// asks a task what its scope is.
//
// The values stay so a declaration still carrying the field VALIDATES rather than
// failing — nothing converges a member's task files, so a member cannot be moved
// off it by a release; `task-declaration-shape` raises it as an advisory rename
// instead, and the field is dropped as each declaration is next edited.
// @deprecated Declares nothing. Name an `invocation_endpoint` if the task needed
//   reach an ordinary session in its repo does not have.
export const SESSION_SCOPES = ['self', 'fleet'];

// What must happen to a task's work item when a recovery path would re-execute it
// (tasks-dispatch DESIGN §6). `requeue` is the safe-side default for sweep-shaped
// work; `needs-human` is the at-most-once dial a one-shot side effect declares.
export const INTERRUPT_POLICIES = ['requeue', 'needs-human'];


// The signal-collector vocabulary (DESIGN §3.3). A task collects only the union
// of what its due tasks declare. `fleet` is canon-only (consumers cannot declare
// it) — that restriction is enforced where signals are collected, not here; the
// shape check only asserts a declared name is a real collector.
export const SIGNAL_NAMES = [
  'commits', 'prs', 'issues', 'branches', 'release',
  'localPacks', 'sharedMount', 'conversationLogs', 'stamp', 'fleet', 'request',
];

// Validate one task declaration. Returns an array of `{ what, fix }` problems —
// empty means the declaration is well-formed. Pure: no I/O, no imports of the
// task itself; the caller supplies the already-loaded default export.
export function validateTaskDeclaration(raw) {
  const decl = normalizeTaskDeclaration(raw);
  if (decl === null || typeof decl !== 'object' || Array.isArray(decl)) {
    return [{ what: 'task.mjs does not default-export a declaration object', fix: 'export default { id, frequency, precondition_signals, agent_model, expected_outcome, agent_instructions, precondition }' }];
  }
  const problems = [];
  const bad = (what, fix) => problems.push({ what, fix });

  if (typeof decl.id !== 'string' || decl.id.trim() === '') {
    bad('the task has no string "id"', 'give the task an "id" matching its directory name');
  }
  // ACCEPTED, not FREQUENCIES: a member's own task file may still carry a retired spelling and
  // must keep running, since nothing converges a member's task files. Stopping a NEW declaration
  // from naming one is the author-time declaration-shape check's job, not this one's — the split
  // is deliberate, and `FREQUENCIES` beside `ACCEPTED_FREQUENCIES` in calendar.mjs is where it is
  // spelled out.
  if (!ACCEPTED_FREQUENCIES.includes(decl.frequency)) {
    bad(`"frequency" ${JSON.stringify(decl.frequency)} is not a legal frequency`, `set one of: ${ACCEPTED_FREQUENCIES.join(', ')}`);
  }
  if (!Array.isArray(decl.precondition_signals) || !decl.precondition_signals.every((s) => SIGNAL_NAMES.includes(s))) {
    bad(`"precondition_signals" must be an array of known signal names`, `use only: ${SIGNAL_NAMES.join(', ')}`);
  }
  if (!MODEL_FAMILIES.includes(decl.agent_model)) {
    bad(`"agent_model" ${JSON.stringify(decl.agent_model)} is not a legal model family`, `set one of: ${MODEL_FAMILIES.join(', ')}`);
  }
  if (!OUTCOMES.includes(decl.expected_outcome)) {
    bad(`"expected_outcome" ${JSON.stringify(decl.expected_outcome)} is not a legal outcome ceiling`, `set one of: ${OUTCOMES.join(', ')}`);
  }
  // automerge — REQUIRED beside `pr` (the legacy ceilings arrive here already
  // carrying theirs), and validated as a policy SHAPE only: whether every named
  // rule resolves is the policy engine's question, answered where the diff is
  // judged, and it fails closed there — never at author time, where the rule set
  // depends on which packs are active.
  if (decl.expected_outcome === 'pr') {
    if (decl.automerge === undefined) {
      bad('a "pr" task declares no "automerge"', 'say what may land unreviewed: "nothing", "anything", or a list of diff classes, e.g. ["comment-only-changes", "readme-changes"]');
    } else {
      const policy = normalizePolicy(decl.automerge);
      if (policy.kind === 'invalid') {
        bad(`"automerge" is not a legal policy: ${policy.reason}`, 'set "nothing", "anything", or a list of rule names, each optionally reject:-prefixed');
      }
    }
  } else if (decl.automerge !== undefined) {
    bad('a "none" task declares "automerge"', 'drop it — a task that opens no pull request has nothing to merge; or set expected_outcome: "pr"');
  }
  // agent_instructions — REQUIRED for an agentic task (agent_model !== 'none'):
  // that's the worker file the agent reads. A `none` task runs no agent, so the
  // field is not applicable and is neither required nor validated when present.
  if (decl.agent_model !== 'none' && (typeof decl.agent_instructions !== 'string' || decl.agent_instructions.trim() === '')) {
    bad('an agentic task (agent_model !== "none") declares no string "agent_instructions"', 'point "agent_instructions" at the worker file beside task.mjs (e.g. "task.md")');
  }
  // precondition(signals, config, item). The third argument is THIS occurrence's own
  // facts — its `Request`, its `Model`, its `Not-before` — for a verdict that is
  // about one target rather than about the repo: a request item's verdict is about
  // the issue it names, which no signal bundle can single out. Backwards compatible
  // by construction, since a precondition simply does not declare an argument it
  // does not read.
  //
  // Three answers, not two: `{ run: true }`, `{ run: false, reason }`, and
  // `{ error }` — the precondition COULD NOT ANSWER. The third is a run failure
  // rather than a verdict (F27): a decline is a decision about the world, and one
  // taken on an API that would not answer is a guess whose write-backs cannot land.
  if (typeof decl.precondition !== 'function') {
    bad('"precondition" is not a function', 'export a precondition(signals, config, item) that returns { run, reason, context? } — or { error } when it could not answer');
  }

  /**
   * model_from_request — OPTIONAL, and reserved to the engine's own built-in task.
   * A task that declares it runs at the model the ITEM names (`Model:`, written by
   * the scheduler run from a write-gated label), falling back to `agent_model` when the item
   * names none. It is the only field that lets anything on an item define behaviour,
   * so it is fenced rather than waved through (DESIGN §16.7): the shape check accepts
   * only `true`, and discovery gives pack tasks no way to be the built-in one.
   */
  if (decl.model_from_request !== undefined && decl.model_from_request !== true) {
    bad(`"model_from_request" ${JSON.stringify(decl.model_from_request)} is not \`true\``,
      'drop the field — only the engine\'s built-in request task reads a model off its item, and every other task names its own agent_model');
  }

  /**
   * session_scope — OPTIONAL, and READ BY NOTHING. Kept validated rather than
   * rejected outright so a lingering declaration still loads: nothing carries a
   * task-file change across the fleet, so a member cannot be migrated off the field
   * by a release, and rejecting it would stop that member's task running over a word
   * that no longer does anything.
   * @deprecated Declares nothing since #974. Drop it; if the task needed reach an
   *   ordinary session in its repo does not have, name an `invocation_endpoint`.
   */
  if (decl.session_scope !== undefined && !SESSION_SCOPES.includes(decl.session_scope)) {
    bad(`"session_scope" ${JSON.stringify(decl.session_scope)} is not a legal session scope`, `drop it — the field is read by nothing; name an "invocation_endpoint" if the task needs wider reach`);
  }

  // Code-work (task-code-work DESIGN §2) — OPTIONAL. The deterministic first phase
  // of task execution, a command the scheduler runs as a subprocess. When present
  // it must be a non-empty, task-local command AND carry a positive-integer
  // code_work_timeout — the hard kill that bounds the subprocess.
  if (decl.code_work !== undefined) {
    if (typeof decl.code_work !== 'string' || decl.code_work.trim() === '') {
      bad('"code_work" is present but not a non-empty string', 'set it to a command whose executable is a script beside task.mjs, e.g. "node prepare.mjs"');
    } else if (escapesTaskDir(decl.code_work)) {
      bad('"code_work" reaches outside the task directory (absolute path or "..")', 'reference a sibling script only, e.g. "node prepare.mjs"');
    }
    if (!isPositiveInt(decl.code_work_timeout)) {
      bad('"code_work" is set but "code_work_timeout" is not a positive integer', 'add "code_work_timeout": the seconds after which the subprocess is killed and the task fails');
    } else if (decl.code_work_timeout * 1000 >= EXECUTING_LEASH_MS) {
      // F17: a code-work legally allowed to outlive the executing leash is reclaimed
      // WHILE ALIVE, and the failure is not one duplicate run but a livelock —
      // every tenure reclaimed before it can finish, code-work re-executing each
      // cycle, the occurrence never converging. The leash is the engine's, so the
      // comparison is made where a declaration is judged.
      bad(`"code_work_timeout" (${decl.code_work_timeout}s) reaches the executor's ${EXECUTING_LEASH_MS / 60e3}-minute claim leash`,
        `bound code_work under ${EXECUTING_LEASH_MS / 60e3} minutes — a code_work that can outlive the leash is reclaimed while still running, and the item livelocks`);
    }
  }

  // --- the work-item queue's three optional declarations (tasks-dispatch DESIGN) ---

  // `schedule_after` — ordering, declared (DESIGN §9). A list of `<pack>/<task>` ids this
  // task yields to WHILE THEY ARE LIVE THIS CYCLE. It compiles to the executor's
  // pick-time yield, never to a `Blocked-by` edge: a standing item that rolls
  // never closes, so blocked-by would starve every dependent of a quiet upstream
  // forever. The engine never learns what any named task does — it reads item
  // states, generically.
  if (decl.schedule_after !== undefined
      && !(Array.isArray(decl.schedule_after)
        && decl.schedule_after.every((s) => typeof s === 'string' && /^[^/\s]+\/[^/\s]+$/.test(s)))) {
    bad('"schedule_after" is not an array of "<pack>/<task>" ids', 'e.g. "schedule_after": ["claudinite-lifecycle/update"] — this task is not scheduled onto an executor while those are live this cycle');
  }

  // `on_interrupt` — the ack-early/ack-late dial (DESIGN §6). Most of this fleet's
  // tasks are sweep-shaped and converge safely on a re-run, so the default is
  // `requeue`. A genuinely one-shot side effect (a store submission, an external
  // notification) declares `needs-human`, and every recovery path that would
  // re-execute it — the leash reclaim, the hand-off retry — converges to triage
  // instead: at-most-once plus a human.
  if (decl.on_interrupt !== undefined && !INTERRUPT_POLICIES.includes(decl.on_interrupt)) {
    bad(`"on_interrupt" ${JSON.stringify(decl.on_interrupt)} is not a legal policy`, `set one of: ${INTERRUPT_POLICIES.join(', ')} (default "requeue")`);
  }

  // `invocation_endpoint` — a NAME, never a URL (DESIGN §12). The repo's config
  // maps the name to the URL and to the name of the Actions secret holding its
  // token, so no vendored pack file carries deployment detail or anything adjacent
  // to a credential. This is also what replaces session_scope: reach is a property
  // of which endpoint a task names.
  if (decl.invocation_endpoint !== undefined
      && !(typeof decl.invocation_endpoint === 'string' && /^[a-z0-9]+(-[a-z0-9]+)*$/.test(decl.invocation_endpoint))) {
    bad('"invocation_endpoint" is not a kebab-case endpoint name', 'name a key from the repo\'s taskScheduler.agenticTaskInvocationEndpoints map, e.g. "fleet" — never a URL');
  }

  // The repo Actions secrets this task needs configured (DESIGN §9). Purely
  // DECLARATIVE — like a pack's adoption `questions`, its job is to drive the ask
  // (adoption interactively, the scheduler by owner issue), not to gate anything
  // here. So the only shape asserted is "a list of names"; whether the repo has
  // actually configured them is a fact about the repo, answered where the secrets
  // bundle is readable, never at author time.
  if (decl.required_secrets !== undefined
      && !(Array.isArray(decl.required_secrets) && decl.required_secrets.every((s) => typeof s === 'string' && s.trim() !== ''))) {
    bad('"required_secrets" is not an array of secret names', 'list the repo Actions secret names this task needs, e.g. ["SOME_API_KEY"]');
  }

  // Execution bound (task-code-work DESIGN §2, §6) — an agentic task MUST
  // declare a positive-integer agent_execution_timeout. There is always a bound
  // on an agentic run; enforcement is best-effort (the executor surfaces the
  // value to the subagent). A `none` task runs no agent, so it needs none.
  if (MODEL_FAMILIES.includes(decl.agent_model) && decl.agent_model !== 'none' && !isPositiveInt(decl.agent_execution_timeout)) {
    bad('an agentic task (agent_model !== "none") declares no positive-integer "agent_execution_timeout"', 'add "agent_execution_timeout": the seconds bounding the agentic run — generous; extreme protection, not a scheduling knob');
  }

  // An agentless task (agent_model: none) runs no agent, so its ONLY work is
  // code-work — a `none` task with no code-work does nothing (DESIGN §4, retiring
  // the in-process inline path). Require the command.
  if (decl.agent_model === 'none' && decl.code_work === undefined) {
    bad('an agentless task (agent_model: "none") declares no "code_work"', 'add "code_work" (a none task does its work in that subprocess) — or give the task an agent_model');
  }

  return problems;
}

// claudinite-growth task: growth-extract — the growth lifecycle's CAPTURE
// stage (per-project-scheduling DESIGN §6). ONE task over BOTH lesson sources:
// it runs the extract-from-activity skill over the window's commits/PRs/issues
// and the extract-from-conversations skill over the captured conversation logs,
// then runs prose-to-checks over what it just wrote to see whether any of it
// upgrades to a check — and lands the whole run through a single PR delivered
// per the repo's delivery settings (task.md → the shared deliver-pr.md
// procedure). Worker: task.md.
//
// The two halves were separate tasks (growth-extract + conversation-extract)
// firing at the same daily anchor, each opening its own PR against the same local
// packs on the same night. They shared the lesson bar, the promotion ladder, the
// dedup surface and the landing mechanics, so splitting them bought nothing and
// cost a second opus dispatch, a second PR, and two runs deduping against a
// corpus the other one was concurrently writing. One task, two source skills.
//
// Self-contained (imports nothing): the whole contract is this default export.

export default {
  id: 'growth-extract',
  frequency: 'daily',
  // The ordering, declared (tasks-dispatch DESIGN §9) — and now the ONLY thing carrying it, since
  // the staggered anchor hours retired with the twice-daily cron (§17.1). This task reads a mount
  // `claudinite-lifecycle/update` converges, so it yields while that task's item is live this
  // cycle and runs the moment it converges — or rolls. The offset only ever implied this; the
  // declaration enforces it.
  schedule_after: ['claudinite-lifecycle/update'],
  precondition_signals: ['commits', 'prs', 'issues'],
  agent_model: 'opus',                   // generalizing/curating lessons is the heaviest judgment, and the default delivery lands the PR with no human review
  expected_outcome: 'pr',
  // Lessons land in the repo's own local packs — prose, and the checks the in-run
  // upgrade pass produces (this pack's merge-rules.json declares both classes).
  automerge: ['claudinite-local-pack-md-changes', 'claudinite-local-pack-check-changes'],
  agent_instructions: 'task.md',
  agent_execution_timeout: 2700,            // two source passes plus the prose-to-checks upgrade — generous bound, extreme protection

  // ONE reason to run: a SUBSTANTIVE default-branch change. A bot bump / [skip ci] /
  // nightly-baselining commit advancing main is not a lesson to extract, and neither
  // is a commit that touched nothing outside `.claudinite/` — this lifecycle's own
  // landed output, which would otherwise re-arm it every night and keep a quiet repo
  // firing forever. `commits.substantiveChange` already applies that classification.
  // It arms the activity half AND means a fresh capture now sits on the logs branch,
  // so the conversation half runs too.
  //
  // There WAS a second arm — a log actually past retention, which existed only so
  // the retention prune still fired on a repo gone quiet. The prune is its own
  // agentless task now (../logs-prune/), so that arm left with it and this opus
  // dispatch no longer happens on nights with nothing to extract.
  //
  // The activity half is scoped by the substantive shas + touched PR/issue numbers
  // passed as binding scope — INCLUDING the PRs merged during the window, whose
  // review discussion is usually its richest lesson source. Context is binding
  // scope and task.md forbids widening past it, so a merged PR the precondition
  // does not name is unreadable to the worker.
  precondition(signals) {
    const commits = signals.commits ?? {};
    if (commits.substantiveChange !== true) {
      return { run: false, reason: 'no substantive default-branch change in the window — nothing to extract' };
    }

    const shas = (commits.list ?? []).filter((c) => c.substantive).map((c) => c.sha.slice(0, 7));
    const prs = signals.prs?.touched ?? [];
    const merged = (signals.prs?.merged ?? []).map((p) => p.number);
    const issues = signals.issues?.touched ?? [];

    const context = [`Activity half IS in scope: the ${shas.length} substantive commit(s) in the window — ${shas.join(', ')}.`];
    if (merged.length) context.push(`PRs merged in the window — read each one's diff and its review discussion: ${merged.map((n) => `#${n}`).join(', ')}.`);
    if (prs.length) context.push(`PRs touched in the window: ${prs.map((n) => `#${n}`).join(', ')}.`);
    if (issues.length) context.push(`Issues touched in the window: ${issues.map((n) => `#${n}`).join(', ')}.`);
    context.push('Conversation half IS in scope: a substantive merge means fresh captures on origin/conversation-logs — run the fresh pass over the recent window.');

    return { run: true, reason: `${shas.length} substantive commit(s) in the window`, context };
  },
};

// claudinite-growth task: growth-dedup — the growth lifecycle's PRUNING stage
// (per-project-scheduling DESIGN §6). Prunes local-pack items the canon now
// covers, keeping items the canon states too generally; lands the prunes through
// one PR against the default branch, delivered per the repo's delivery settings.
// Worker: task.md.
//
// The old fleet's `relevantCanonChanged` becomes the `sharedMount` signal — a
// declared pack's vendored files moving is the local echo of "the canon this repo
// mounts changed" — so movement, never the calendar, is what wakes this: a quiet
// repo with no local packs skips.
//
// The cadence is WEEKLY, not daily (#582). A member's mount moves most nights —
// baselining converges it daily — so a daily anchor started this opus session, and
// the PR behind it, nearly every night. Pruning is not latency-sensitive: a
// local item the canon has already absorbed stays harmlessly correct until it goes,
// so the daily anchor bought noise rather than freshness. Nothing is missed by the
// move — both signals below are WINDOW-scoped, and an item's collection window is
// its own task's period, so the weekly run sees a full 7 days of canon and
// local-pack movement batched into one run.
//
// The whole contract is this default export; the only imports are the shared
// constants the local-pack policy scope is built from, never task logic.

import { sep } from 'node:path';
import { LOCAL_PACKS_SUBDIR, LEGACY_LOCAL_PACKS_SUBDIR } from '../../../../engine/pack_loader/pack-registry.mjs';

// The two roots a local pack may sit under during the rename window, as the
// '/'-separated prefixes a policy scope takes (the constants are platform-joined).
const LOCAL_PACK_ROOTS = [LOCAL_PACKS_SUBDIR, LEGACY_LOCAL_PACKS_SUBDIR]
  .map((subdir) => subdir.split(sep).join('/'));

export default {
  id: 'growth-dedup',
  frequency: 'weekly',             // the weekly anchor — prunes against the mounted canon that morning's 02:00 baselining converged (DESIGN §2)
  precondition_signals: ['localPacks', 'sharedMount', 'commits'],
  agent_model: 'opus',                   // proving the canon genuinely covers a local item — and telling coverage from "stated too generally" — is a judgment call
  expected_outcome: 'pr',
  // A prune may remove lines or cut one down, never grow one — and only inside
  // the local packs it prunes; the same edit to the repo's own prose is somebody
  // else's document. A `review` member still reviews.
  automerge: LOCAL_PACK_ROOTS.map((root) => `under:${root} && markdown-trims`),
  agent_instructions: 'task.md',
  agent_execution_timeout: 1800,            // proving canon coverage per local item — generous bound, extreme protection

  // The deterministic half: what the mounted canon ADDED in the window — prose
  // lines and new checks alike — posted as a comment on the run's own work item,
  // the brief the agentic phase starts from. Reading a diff is code work, and the
  // pack owns it: the `sharedMount` signal names the packs that moved and stops
  // there, deliberately, because a signal is a cheap gate any task may declare,
  // not one task's research. The hand-off is unconditional (worker.mjs) —
  // the precondition below is the only place this run may be declined.
  code_work: 'node worker.mjs',
  code_work_timeout: 600,                     // one commit listing plus a read per window commit

  // Gate: the repo must actually track local packs (no local packs → nothing to
  // prune, self-skip). Given local packs, run when the mounted canon this repo
  // CARES about moved — a declared pack's vendored files changed (`sharedMount`),
  // which can newly cover a local item — or the repo's own local packs changed in
  // the window (a fresh local item to re-check against the canon). A quiet repo
  // with local packs but no relevant movement skips.
  precondition(signals) {
    const local = signals.localPacks ?? {};
    // `present` is null when the scheduler couldn't determine it; treat only an
    // explicit false as "definitely no local packs to prune".
    if (local.present === false) {
      return { run: false, reason: 'no local packs — nothing to prune' };
    }
    const changedPacks = signals.sharedMount?.changedPacks ?? [];
    const canonMoved = changedPacks.length > 0;
    const localChanged = local.changedInWindow === true;

    if (canonMoved) {
      return { run: true, reason: `declared pack(s) changed in the mounted canon: ${changedPacks.join(', ')} — local items may now be covered`, context: [`Re-check local items against these newly-changed canon packs: ${changedPacks.join(', ')}.`] };
    }
    if (localChanged) {
      return { run: true, reason: 'local packs changed in the window — re-check the fresh items against the mounted canon' };
    }
    return { run: false, reason: 'local packs present but no relevant canon or local movement in the window' };
  },
};

// claudinite-growth task: rule-revalidation — re-probe the pack rules whose
// truth lives OUTSIDE this repo. A rule saying "the harness rejects X", "the
// Action's token cannot reach Y", "MCP tool Z exists" was true of the environment
// on the day it was written, and nothing in the repo goes red when the platform
// moves under it: the prose stays green, sessions keep following it, and the cost
// lands as a session spent on a path that closed months ago. This task re-runs the
// probe behind each such claim and corrects what no longer holds.
//
// Scope is the pack's existing `pack_paths` config — the same key the sibling
// prose-to-checks-sweep reads, so a repo names its capture surface once: a
// consuming repo revalidates only its OWN local packs, and Claudinite (which
// configures `packs`) revalidates the whole canon — so every pack's claims are
// re-probed in the one repo that can fix them, exactly once across the fleet.
//
// Self-contained (imports nothing): the whole contract is this default export.

// The repo's own capture surface — a consumer revalidates only its LOCAL packs.
const DEFAULT_PACK_PATHS = ['.claudinite/local/packs'];

export default {
  id: 'rule-revalidation',
  frequency: 'weekly',             // the environment moves on a platform's clock, not this repo's — see the cadence note
  precondition_signals: [],              // nothing in the repo signals that the world changed; the trigger is the calendar
  agent_model: 'opus',                   // designing a safe probe per claim, and reading a null result correctly, is heavy judgment
  expected_outcome: 'pr',
  automerge: ['claudinite-local-pack-md-changes'], // rewrites confined to the repo's own local-pack prose land themselves; anything wider parks
  agent_instructions: 'task.md',
  agent_execution_timeout: 2700,         // reading the corpus + running real probes — a generous bound

  // WEEKLY, and with no signal arm at all. Every other growth task waits for the
  // repo to move; this one exists precisely because the repo does NOT move when
  // its claims expire — the harness ships, a token's scope narrows, an MCP server
  // drops a tool, and the only local evidence is a session failing later. So the
  // calendar is the whole trigger, and the slice-per-run discipline in task.md is
  // what keeps a standing corpus affordable.
  precondition(_signals, config) {
    const paths = Array.isArray(config?.pack_paths) && config.pack_paths.length ? config.pack_paths : DEFAULT_PACK_PATHS;
    return {
      run: true,
      reason: `weekly revalidation of environment-dependent claims in ${paths.join(', ')} (no-ops cheaply when every probe still passes)`,
      context: [
        `Pack paths to revalidate (these, and only these): ${paths.join(', ')}.`,
        'Probe read-only. A claim whose probe would write, delete, merge, publish, or notify is verified from authoritative documentation instead — never by performing it.',
        'A probe this session lacks the reach to run is UNPROBED, not disproven: leave the rule exactly as it stands and log it.',
      ],
    };
  },
};

// claudinite-growth task: prose-to-checks-sweep — mine a repo's EXISTING pack
// prose for always-testable rules the conversion missed and convert the strongest
// ones (per-project-scheduling redesign). A per-repo task: every repo declaring the
// growth pack sweeps its OWN packs. Which pack paths it works is a config setting,
// `pack_paths`, defaulting to the repo's own local packs; Claudinite itself sets it
// to ALSO include its core `packs/` (projects are not expected to improve core canon
// packs — only Claudinite does). The method is owned by the prose-to-checks skill.
//
// The whole contract is this default export; the only imports are the shared
// constants the local-pack policy scope is built from, never task logic.

// The repo's own capture surface — a consumer improves only its LOCAL packs.
const DEFAULT_PACK_PATHS = ['.claudinite/local/packs'];

import { sep } from 'node:path';
import { LOCAL_PACKS_SUBDIR, LEGACY_LOCAL_PACKS_SUBDIR } from '../../../../engine/pack_loader/pack-registry.mjs';

// The two roots a local pack may sit under during the rename window, as the
// '/'-separated prefixes a policy scope takes (the constants are platform-joined).
const LOCAL_PACK_ROOTS = [LOCAL_PACKS_SUBDIR, LEGACY_LOCAL_PACKS_SUBDIR]
  .map((subdir) => subdir.split(sep).join('/'));

export default {
  id: 'prose-to-checks-sweep',
  frequency: 'weekly',                   // works the STANDING backlog a slice at a time — see the cadence note below
  precondition_signals: [],              // the backlog is standing prose, not a windowed signal
  agent_model: 'opus',                   // judging convertibility and authoring checks + fixtures is heavy judgment
  expected_outcome: 'pr',
  // A conversion removes the prose line and writes the check that replaces it —
  // both classes are this pack's merge-rules.json. In the canon home the sweep
  // works `packs/`, which neither class covers, so a canon round still parks.
  // The prose side is line removals from local-pack Markdown — said inline,
  // since the built-in class already means exactly that; the check side needs
  // the pack's own file-name matcher.
  automerge: [
    ...LOCAL_PACK_ROOTS.map((root) => `under:${root} && markdown-line-removals`),
    'claudinite-local-pack-check-changes',
  ],
  agent_instructions: 'task.md',
  agent_execution_timeout: 2700,         // reading the packs + authoring a check with fixtures — generous bound

  // WEEKLY, not daily. Freshly written prose no longer waits for this task at all:
  // growth-extract runs the prose-to-checks skill over its OWN additions as the last
  // step of every capture run, so a convertible rule is converted the night it is
  // learned. What is left here is the standing backlog — prose that has already
  // survived at least one upgrade pass — and that set changes on a weekly clock, not
  // a daily one. Daily re-read the same dry corpus with an opus dispatch and an
  // owner-gated PR nobody was waiting on.
  precondition(_signals, config) {
    const paths = Array.isArray(config?.pack_paths) && config.pack_paths.length ? config.pack_paths : DEFAULT_PACK_PATHS;
    return {
      run: true,
      reason: `weekly prose-to-checks backlog sweep over ${paths.join(', ')} (no-ops cheaply when dry)`,
      context: [`Pack paths to sweep (work ONLY these; never a read-only mounted canon pack under .claudinite/shared/): ${paths.join(', ')}.`],
    };
  },
};

// claudinite-growth task: logs-prune — retention on the `conversation-logs`
// branch. `agent_model: 'none'` with `code_work: 'node worker.mjs'`: the whole pass
// is deterministic code the scheduler runs as a subprocess — no agent, no dispatch
// issue, seconds of runtime. The same shape usage-fold already has over the same
// branch.
//
// WHY IT IS NOT PART OF growth-extract. Deleting a capture past retention is
// arithmetic on dates over an orphan branch — which is why the extract worker had
// to spend prose forbidding an agent to merge that branch or rewrite its history.
// Coupled to the opus run it also kept that run's precondition carrying a second
// arm whose only job was to fire the prune on a quiet repo, so a repo with nothing
// to extract still paid an opus dispatch on the nights one log aged out.
//
// WHAT MAKES AGE ENOUGH. The prune used to be coupled to a judgment step — an aged
// log got a final pass before deletion — so pruning on the calendar risked deleting
// a capture nothing had read. What removes the risk is the extract run's READING
// WINDOW, not a per-file handshake between the two tasks: growth-extract reads from
// the oldest end of the branch on every run, against a retention measured in days,
// so a capture reaches retention having been read. The extract-from-conversations
// skill owns that window; this task owns the arithmetic.
//
// Self-contained (imports nothing): the whole contract is this default export.

export default {
  id: 'logs-prune',
  frequency: 'daily',                    // a log ages out on wall time; the branch is read locally, so a run costs seconds
  precondition_signals: ['conversationLogs'],
  agent_model: 'none',                   // pure code — no agent (task-code-work DESIGN §4)
  // It opens no PR: its whole write is remove commits on the non-default logs
  // branch, which is outside the outcome taxonomy (per-project-scheduling DESIGN §1).
  expected_outcome: 'none',
  code_work: 'node worker.mjs',
  // One ls-remote, one fetch, one tree read, at most one push — against a branch
  // whose size retention itself bounds. Seconds. The bound is protection against a
  // hung network call, not headroom for work, so it sits just past the slowest
  // plausible fetch rather than at the leash.
  code_work_timeout: 60,

  // The AGE arm, inherited from growth-extract's second precondition arm — which
  // existed only to fire the prune on a quiet repo and left with it.
  //
  // It tests the age, not "a branch exists and retention is configured": that pair
  // is true on every capturing repo every day. The worker is cheap enough that a
  // run finding nothing costs seconds, but a precondition that is true forever
  // once true is not a trigger at all.
  precondition(signals) {
    const logs = signals.conversationLogs ?? {};
    const retention = logs.retentionDays;
    const oldest = logs.oldestLogAgeDays;
    if (logs.present !== true) return { run: false, reason: 'no conversation-logs branch — nothing captured yet' };
    if (typeof retention !== 'number') return { run: false, reason: 'retention_days is unset — capture-only adoption, the prune deletes nothing' };
    if (!(typeof oldest === 'number' && oldest > retention)) {
      return { run: false, reason: `no log older than retention ${retention}d — nothing to prune` };
    }
    return { run: true, reason: `oldest log ${oldest.toFixed(1)}d old vs retention ${retention}d` };
  },
};

// tidy-repo task: tidy-issues — the ACTING half of the tidy sweep
// (per-project-scheduling DESIGN §6). Triages the issues the window touched, and
// re-checks every open issue when the default branch moved substantively (a real
// commit can implement an old issue without the issue itself being touched).
// Worker: task.md. PRs are a separate task: one dimension per task, each with its
// own trigger, scope, and tracker — no ordering barrier between them.
//
// Self-contained (imports nothing): the whole contract is this default export.

export default {
  id: 'tidy-issues',
  frequency: 'daily',                       // the 04:00 anchor (DESIGN §2) — the one tidy dimension that ACTS, so latency matters
  precondition_signals: ['issues', 'commits'],
  agent_model: 'sonnet',                    // "implemented in main" is a judgment call against main's current content
  expected_outcome: 'none',                 // writes ISSUES only (the triage actions + its own tracker) — never a PR
  agent_instructions: 'task.md',
  agent_execution_timeout: 900,             // one dimension over a bounded issue list

  // ONE trigger, and one widener. The trigger is a touched issue: if no issue was
  // filed, commented on, labelled, or reopened in the window, this task does not
  // run — the existing pile got the same triage last time it moved, and re-deriving
  // it costs an agent run per day to rewrite the tracker with itself.
  //
  // The task's own triage comments are the one write that lands on the issues this
  // gate watches, so re-announcing a standing verdict would arm tomorrow's run
  // forever (#988). single-issue-triage does not make that write; nothing here
  // filters it out after the fact.
  //
  // A substantive default-branch move WIDENS an already-triggered run to every open
  // issue, because a real commit can implement an issue the issue itself never
  // recorded — but it no longer wakes the task by itself. On any repo whose `main`
  // moves most days that widening was firing daily, which is a full re-triage of
  // every open issue every day: exactly the "went over the existing ones with
  // nothing new" this gate exists to prevent. A housekeeping-only move (a nightly
  // baseline commit, a bot bump) implements nothing, so it does not widen at all.
  precondition(signals) {
    const substantive = signals.commits?.substantiveChange === true;

    // A `task:*` label is the scheduler's own marker, stamped on a queue work item
    // when it is created and carried for its whole life. The issues signal hides
    // those items by TITLE prefix, so one the queue files under any other title
    // reaches this task and gets triaged as project work. The label is the
    // invariant, so it is what this filters on — and it filters BOTH ways: such an
    // issue is neither a touch that triggers a run nor a target inside one.
    const queueItem = (i) => (i.labels ?? []).some((l) => String(l).startsWith('task:'));
    const open = (signals.issues?.open ?? []).filter((i) => !queueItem(i)).map((i) => i.number);
    const inScope = new Set(open);
    const touched = (signals.issues?.touched ?? []).filter((n) => inScope.has(n));

    // Between the signal's title filter and the label filter above, none of
    // Claudinite's own issues — the queue's work items, its schedule board, the
    // standing trackers — can be triaged as project work or count as the touch
    // that triggers a run.
    if (!touched.length) return { run: false, reason: 'no issues touched in the window' };

    const scope = substantive ? open : touched;
    return {
      run: true,
      reason: substantive
        ? `issues touched, and main moved substantively — re-check all ${scope.length} open issue(s) against it`
        : 'issues touched in the window',
      context: [`Issues to triage: ${scope.map((n) => `#${n}`).join(', ')}.`],
    };
  },
};

// tidy-repo task: improve-comments — the one tidy dimension whose subject is the
// repo's own source rather than its GitHub objects. The other three assess or act
// on issues, PRs and branches; this one reads a slice of the code AS COMMENTS and
// fixes what it finds there. Worker: task.md, which runs the improve-comments skill
// and nothing else.
//
// WHY IT IS A TASK AT ALL: a comment decays as the code around it changes and
// nothing makes it fail. No test goes red, no check fires, and no session working on
// something else will stop to fix one. The only way a repo's comments get read as
// comments is a pass whose whole job that is.
//
// WEEKLY. Comment drift is not latency-sensitive — a stale comment costs the next
// reader, whenever that is — and the window's commits are what name the files whose
// comments are likeliest wrong, so a weekly window is a bigger and better-targeted
// scope than a daily one for the same session cost.
//
// Self-contained (imports nothing): the whole contract is this default export.

// The pinned commit subject the run's own scope gate keys on, stated in task.md and
// enforced by the skill's `improve-comments-scope` check. Kept in step by the
// declaration test beside this pack's other tests.
const RUN_TITLE = 'Claudinite tidy: improve comments';

// The mount, excluded from every round's scope. `.claudinite/shared/` is vendored
// and the next converge replaces it whole, so a comment improved there is gone by
// morning; `.claudinite/local/` is written by the growth tasks. Neither is the
// repo's own source, and the converge touches them most nights, so left in they
// crowd the round's cap. Kept in step with the same prefix in the
// improve-comments-scope gate by the test beside that check.
const MOUNT_PREFIX = '.claudinite/';

// How many of the window's changed files one round reads. A busy week can touch
// hundreds, and a session handed all of them skims; the rest are next round's, and
// the run says so rather than presenting a truncated list as the whole window.
const MAX_FILES = 40;

export default {
  id: 'improve-comments',
  frequency: 'weekly',                   // the weekly anchor (DESIGN §2); the window's commits are the scope
  precondition_signals: ['commits', 'prs'],
  agent_model: 'opus',                   // whether a comment carries a why the code cannot state is the judgment here, and a wrong call lands in the repo's source
  // A ceiling, not a plan: the repo's own delivery setting decides whether the
  // PR lands unreviewed, and a `review` member still gets it left open. The
  // policy states in the contract what makes the pass safe to land unattended —
  // the diff can only ever be comment text and README content — and the pass's
  // own scope gate (the skill's `improve-comments-scope` check) reds the same
  // boundary on every branch wearing its title, armed or not.
  expected_outcome: 'pr',
  automerge: ['comment-only-changes', 'readme-changes'],
  agent_instructions: 'task.md',
  agent_execution_timeout: 1800,

  // Two gates, in order. Did anything land in the window — comments decay against
  // code, so a quiet week has nothing to re-read. Then: is this pass's previous PR
  // still open, which means it did not land (a `review` member's, or one whose CI
  // never concluded), and a second sweep over files the first one may already have
  // touched would stack on it. Reading the pending PR's TITLE rather than a marker
  // on the item means a PR the owner opened by hand from this branch gates the
  // round too.
  precondition(signals) {
    const openPrs = signals.prs?.open ?? [];
    const pending = openPrs.find((p) => String(p.title ?? '').startsWith(RUN_TITLE));
    if (pending) {
      return {
        run: false,
        reason: `PR #${pending.number} is this pass's previous round, still open — this round waits for it to land rather than stack a second sweep on it`,
      };
    }

    const commits = signals.commits;
    if (!commits?.substantiveChange) {
      return { run: false, reason: 'no substantive commit in the window — nothing moved for a comment to have drifted from' };
    }
    const allTouched = commits.touchedPaths ?? [];
    if (!allTouched.length) {
      return { run: false, reason: 'the window\'s commits name no changed path — nothing to read' };
    }
    const touched = allTouched.filter((p) => !p.startsWith(MOUNT_PREFIX));
    if (!touched.length) {
      return { run: false, reason: `the window's changed paths are all under ${MOUNT_PREFIX} — the mount is not this repo's source to comment` };
    }

    // A window can carry more files than one session should read as comments. Name
    // the cap and what it dropped rather than hand over a silently truncated list
    // that reads as the whole window.
    const scope = touched.slice(0, MAX_FILES);
    const dropped = touched.length - scope.length;
    return {
      run: true,
      reason: `${touched.length} path(s) changed in the window`,
      context: [
        `Read the comments in exactly these files, and no others: ${scope.join(', ')}.`,
        ...(dropped ? [`${dropped} further path(s) changed in the window and are NOT in scope this round — say so in the wrap-up so the next round is not read as a full sweep.`] : []),
        'A file whose comments are already right yields no edit — that is the common outcome and a good one.',
      ],
    };
  },
};

// tidy-repo task: tidy-prs — the read-only PR half of the tidy sweep
// (per-project-scheduling DESIGN §6). One weekly full sweep over every open PR:
// which should stay open, which are closeable. Recommends; never closes. Worker:
// task.md. Issues are a separate task — one dimension per task, each with its own
// trigger, scope, and tracker, so there is no ordering barrier.
//
// WEEKLY, and full every time it runs — but it only runs when a PR actually moved
// in the window. A PR verdict is a standing recommendation for a human, not a
// same-day alert, so re-deriving the whole picture once a week beats a daily partial
// one — and "weekly" is a frequency DECLARATION, never a gate trick inside a daily
// task (DESIGN §3). What "full" does not mean is unconditional: an untouched set of
// open PRs yields last week's verdicts again, so the sweep is gated on newness even
// though its scope stays full.
//
// Self-contained (imports nothing): the whole contract is this default export.

export default {
  id: 'tidy-prs',
  frequency: 'weekly',                      // the weekly anchor (DESIGN §2); the full sweep is the declaration
  precondition_signals: ['prs'],            // the open set is the scope; `touched` is the gate
  agent_model: 'sonnet',                    // superseded / already-in-main are judgment calls on the diff
  expected_outcome: 'none',                 // assess-only: never closes, merges, or comments on a PR; writes only its tracker
  agent_instructions: 'task.md',
  agent_execution_timeout: 900,             // a full sweep, but one cheap read-only verdict per PR

  // Two gates, in order. Is there anything open to assess — a repo with no open PRs
  // stays silent. Then: did any open PR get opened or updated in the window. If none
  // did, the picture is the one the tracker already holds and another pass would
  // rewrite it with itself. When one did move, scope is still the FULL open set: a
  // PR verdict is relative to the others (superseded-by), so the mover cannot be
  // judged alone. `touched` counts the newly OPENED ones too — the collector derives
  // it from the open listing's `updated_at`, which a new PR carries.
  precondition(signals) {
    const open = (signals.prs?.open ?? []).map((p) => p.number);
    if (!open.length) return { run: false, reason: 'no open PRs' };

    const touched = signals.prs?.touched ?? [];
    if (!touched.length) {
      return { run: false, reason: `no PR opened or updated in the window — the standing picture over ${open.length} open PR(s) is unchanged` };
    }

    return {
      run: true,
      reason: `${touched.length} PR(s) moved in the window — full sweep over ${open.length} open PR(s)`,
      context: [`PRs to assess (read-only — recommend closes, never close): ${open.map((n) => `#${n}`).join(', ')}.`],
    };
  },
};

// product-wiki task: wiki-growth — one research-and-refine pass over the repo's
// product wikis (per-project-scheduling DESIGN §6). Worker: task.md.
//
// WEEKLY, not daily and not commit-gated: research arrives on the world's clock,
// not the repo's, and a nightly high-model pass economically pressures
// fabrication (the Karpathy LLM-wiki cadence). The `commits` signal is declared
// only so the precondition can note recent product-relevant movement in context;
// the run itself is scheduled by frequency, not triggered by a commit.
//
// The pending-wiki-change gate lives HERE, in the precondition (DESIGN §12: the
// precondition is the ONLY decision point — it used to be a task.md preflight,
// which was the agentic phase deciding to skip a run its precondition had
// already granted). It is not subsumed by the queue: the queue guards at most one
// live ITEM per task — it never looks at pull requests, and a completed run closes
// its item while leaving the growth PR open for review. This gate is the only thing standing between an unreviewed
// PR and a second round of research stacked on top of it.
//
// Self-contained (imports nothing): the whole contract is this default export.

// The wiki tree, root-anchored: the prefix this precondition both declines on
// (a pending change to it) and adds context for (a landed change to it), and the
// scope of what the round's own PR may land unreviewed.
const WIKI_ROOT = 'product-wiki/';

export default {
  id: 'wiki-growth',
  frequency: 'weekly',             // fires at the weekly anchor (DESIGN §2) — the world's clock, not the repo's
  precondition_signals: ['commits', 'prs'],
  agent_model: 'opus',                   // open-web research + curation is the heaviest judgment in the task set
  expected_outcome: 'pr',
  // Markdown, and only inside the tree the round is allowed to grow: `&&` is the
  // intersection, so a doc elsewhere in the repo and a non-doc file inside the
  // wiki both park the round for review. On a member whose mount predates this
  // vocabulary the policy reads as invalid, which is the same park — never a
  // wider merge.
  automerge: [`under:${WIKI_ROOT} && doc-changes`],
  agent_instructions: 'task.md',
  agent_execution_timeout: 2700,            // open-web research is the least predictable of the tasks — very generous

  // The weekly anchor is the trigger — a wiki grows on research availability, not
  // repo activity — EXCEPT while an open PR carries a pending change to the wiki
  // tree: then this run is declined here, in code, rather than granted and
  // abandoned by the agent. Reading the pending CONTENT rather than a marker the
  // worker applied to its own PR means a human's wiki edit in flight gates the
  // round too. The worker's own stop condition (no citable material → no branch,
  // no PR) remains the legal empty OUTCOME of a run that did happen.
  precondition(signals) {
    const openPrs = signals.prs?.open ?? [];
    const pendingWikiPr = openPrs
      .find((p) => Array.isArray(p.changedPaths) && p.changedPaths.some((f) => f.startsWith(WIKI_ROOT)));
    if (pendingWikiPr) {
      return {
        run: false,
        reason: `PR #${pendingWikiPr.number} has a pending ${WIKI_ROOT} change — research waits for its review, so a second unreviewed round is never stacked on it`,
      };
    }
    // A PR whose paths could not be read (an unreadable file list, or an engine
    // older than the one that resolves them) is UNKNOWN, never "clear": the whole
    // point of the gate is that an unreviewed round is worse than a skipped one.
    const opaquePr = openPrs.find((p) => !Array.isArray(p.changedPaths));
    if (opaquePr) {
      return {
        run: false,
        reason: `PR #${opaquePr.number}'s changed paths could not be read, so whether a ${WIKI_ROOT} change is pending is unknown — a skipped round is cheaper than an unreviewed one stacked on it`,
      };
    }
    const touched = signals.commits?.touchedPaths ?? [];
    const wikiMoved = touched.some((p) => p.startsWith(WIKI_ROOT));
    const context = wikiMoved
      ? ['The product-wiki tree moved in the window — spot-check any pages whose cited claims the change may have superseded.']
      : [];
    return { run: true, reason: 'weekly product-wiki growth pass', context };
  },
};

// basics task: update — the versioned engine/pack update flows, run by a repo on
// itself (#768 — see the versioned-updates design there). The successor to
// `baselining`, and since Phase 5 deleted that, the only thing that maintains a
// member's mount: there is no mechanism flag left to consult, and the block that
// held one is gone (#1252).
//
// Two stages, like baselining's. The DETERMINISTIC flows are `code_work`
// (worker.mjs): they converge the mount, run the version-ranged migrations, gate on
// the converged tree's self-test, open the PR, and act on the terminal. The AGENT
// stage runs only when the pack flow's apply stage is needed — the pack's new rules
// meeting member-authored content the canon has never seen.
//
// Self-contained (imports nothing) so the scheduler, executor, and a human all load
// it standalone — the whole contract lives in this default export.

export default {
  id: 'update',
  frequency: 'daily',                    // the head of the morning chain — everything that reads a converged mount declares `schedule_after:` this
  precondition_signals: ['stamp', 'sharedMount'],
  agent_model: 'sonnet',                 // the apply stage only — most runs are agentless
  expected_outcome: 'pr',
  automerge: 'anything',             // the converge replaces the vendored mount wholesale — the one lane whose trust is the repo's delivery setting, not a diff class
  agent_instructions: 'task.md',

  code_work: 'node worker.mjs',
  code_work_timeout: 900,
  agent_execution_timeout: 1800,

  // PURE over the collected signals. It gates only that the worker RUNS; the worker
  // owns every decision after that — and that division is why this asks almost nothing.
  //
  // THE ONE QUESTION WORTH ASKING IS UNAVAILABLE HERE. "Is this member behind the
  // canon?" needs the canon's versions, and the scheduler Action deliberately does not
  // read canon (DESIGN §3.3): `stamp.canonHead` is always null and no signal carries
  // them. Two proxies have stood in for it and both answered a different question. A
  // datetime in the declaration recorded the last FULL re-vendor, so a member converging
  // nightly read as months overdue forever (#1252). Local movement in the window —
  // "the mount converged and no declared pack's files changed" — reads as "nothing
  // happened here lately", which is equally true of a member that is current and one
  // that canon moved past an hour after its own converge (#1344). The second proxy left
  // LaughCounter and TLDR four packs behind for a day, declining their own updates,
  // with no way out: a forced wake mints the item and the precondition is re-evaluated
  // at pick, so the force converges to a no-op.
  //
  // So it no longer guesses. The asymmetry settles it: declining wrongly costs
  // permanent, silent staleness nothing in the member can repair, while running
  // wrongly costs one converge that finds nothing and exits. A daily no-op is the
  // cheaper mistake by a wide margin.
  precondition(signals) {
    const stamp = signals.stamp ?? {};
    if (!stamp.present) {
      return { run: false, reason: 'no vendored mount (no installed versions) — nothing to update' };
    }
    return {
      run: true,
      reason: 'the mount is due an update pass',
      context: [
        'The deterministic flows have already run: the mount is converged, the version-ranged migrations applied, and the update PR is open.',
        'Your job is only the apply stage — bring this repo\'s own content in line with the updated pack rules on that branch, and verify the executor routine. Do not re-run the mechanical converge.',
      ],
    };
  },
};

// claudinite-growth task: adopt-requested-packs — adopt the packs this repo's
// `add-packs` work-list issues ask for, in THIS repo, by this repo's own agent.
//
// THE MEMBER HALF OF THE FLEET FAN-OUT (#749, folded onto the queue's own request
// mode in #1119). A fleet enforcer (the claudinite-fleet-sheepdog pack's
// fleet-add-missing-packs task) decides a member is missing packs — a weekly
// fingerprint scan SUSPECTS them, or the owner REQUESTS them by hand with config
// and interview answers decided — and, per member, converges one `add-packs`
// work-list issue HERE, marked `task:origin:ad-hoc` with a `Task:` field naming
// this task. THE ISSUE IS THEN THE WORK ITEM: this repo's own hourly scheduler run
// adopts it, its own executor picks it up, and its agent adopts with the repo
// checked out and lands one reviewed PR here. No agent anywhere needs cross-repo
// access, which is the failure the first design hit in production.
//
// There is no code-work phase and no gate in front of the agent: an item exists
// only because an issue was marked, so "is there work?" is answered by the item's
// existence. (Before the fold it was answered by counting labelled issues, because
// the enforcer woke a standing item that had no idea why it was awake.)
//
// `frequency: 'manual'` — never due on any cadence. The work only exists when the
// fleet places it. (A member whose run died is re-asked by clearing the issue's
// status, which the enforcer does whenever it rewrites a changed ask, and by the
// fleet's next weekly visit.) A repo outside any fleet simply never runs this.
//
// WHY sonnet: the deciding is mostly done. A REQUESTED issue carries the exact
// declaration entries to write; a SUSPECTED one needs the bounded judgment "is this
// fingerprint's suspicion right for this repo", made against a checkout, with the
// pack's own README stating its boundary.
//
// WHY IT LANDS UNATTENDED (#1453). This ceiling used to be `open-pr`, on the
// reasoning that a new pack switches on checks in the member's CI and so should
// always be reviewed. In practice the review never came: ClaudiniteCanary#133 did
// its work correctly, opened its PR, and sat parked for approval for ELEVEN days
// while the adoption never reached the repo it was for. A gate nobody walks through
// is not a safeguard, it is where the work stops.
//
// What that trades away, stated because it is a reversal: a member's gate surface
// can now change with no human in front of it. The adoption PR still runs that
// member's own checks before it merges, so a pack whose checks fail there cannot
// land — but a pack whose checks pass and is merely unwanted now arrives unasked.
// The fleet enforcer's `add-packs` issue remains the place to say no, before the
// work is placed rather than after it is done.
//
// Self-contained (imports nothing): the whole contract is this default export.

export default {
  id: 'adopt-requested-packs',
  frequency: 'manual',                   // fired by the fleet enforcer when it places work here — never due on its own
  precondition_signals: [],              // no signal — the work list arrives by push, not by observation
  agent_model: 'sonnet',                 // applies existing packs by an existing skill; confirmation judgment is bounded and reviewed
  expected_outcome: 'pr',
  // Lands unattended (see the note above on what that trades away) within what an
  // adoption actually writes: the declaration, the re-vendored mount (this pack's
  // merge-rules.json declares both) and the regenerated rules index. A pack whose
  // adoption scaffolds workflow files parks for review — fail-safe, and rare.
  automerge: ['claudinite-shared-packs', 'claudinite-settings-updates', 'generated-file-changes'],
  agent_instructions: 'task.md',
  // Adopting packs is a declaration edit, an interview transcription, a re-vendor, a
  // scaffold and a PR. Generous, because it is a runaway bound and not a scheduling
  // knob.
  agent_execution_timeout: 3600,

  // Never due on its own — `manual` means the scheduler run never instantiates this task,
  // so an item exists ONLY because the fleet enforcer (or a human) created one,
  // and that IS the request. Hence run: true. The queue evaluates this verdict at
  // pick (tasks-dispatch DESIGN §6.4), unlike the slot mechanism where a forced
  // run bypassed it; a no-go here has no anchor to roll to, so it would close the
  // enforcer's own item `task:obsolete` without running.
  precondition() {
    return { run: true, reason: 'a work item for this manual lever exists, which is the request to run it' };
  },
};

// basics task: task-janitor — the THIRD responsibility of the scheduled-task
// machinery (owner, 2026-08-06). The scheduler run CREATES and readies work items, the
// executor EXECUTES exactly the one item it picked, and this task — alone —
// cleans up after both: items stuck ready past their period, items left wearing
// no state label by a torn transition, and a health review of the open set.
// Neither the scheduler run nor the executor does any of that; a task execution cares only
// about its own item, and recovery lives here, in code, once a day.
//
// It also sweeps what the retired slot mechanism left behind: the last slot runs
// filed `[claudinite-task]` dispatch issues in members, and nothing else closes
// them out. That half retires when the fleet's are gone, not before.
//
// The scheduler run reclaims a dead executor claim itself, hourly — this task is the
// slower backstop for what the scheduler run's deterministic label mechanics cannot see.
//
// `agent_model: 'none'` + code_work: the whole pass is deterministic code the
// executor runs as code-work — no agent phase, fully automatic.
//
// Self-contained (imports nothing): the whole contract is this default export.

export default {
  id: 'task-janitor',
  frequency: 'daily',
  precondition_signals: [],
  agent_model: 'none',                   // pure code — cleanup needs no judgment
  expected_outcome: 'none',              // labels and comments only, never a PR
  code_work: 'node worker.mjs',
  // One repo-wide issue search plus a handful of label/comment writes — seconds.
  code_work_timeout: 300,

  // Unconditional, and honestly so: the sweep itself is the cheap way to learn
  // whether anything needs cleaning, and a quiet repo costs one search. The
  // precondition is the ONLY decision point in a task's life — this one simply
  // always decides yes.
  precondition() {
    return { run: true, reason: 'daily dispatch-issue cleanup and health review' };
  },
};

// claudinite-growth task: usage-fold — the per-repo usage aggregate
// (skill-usage-metrics DESIGN §5). `agent_model: 'none'` with
// `code_work: 'node worker.mjs'`: the whole pass is deterministic code the
// executor runs as code-work — no agent phase, seconds of runtime.
//
// WHY: a skill is MOUNTED per repo, but mounting only puts a name and a one-line
// description into the session prompt — actually LOADING it is model discretion, and
// nothing recorded whether it ever happened. The only evidence is the session
// transcript, which is ephemeral and dies at retention on the logs branch. So the
// promotion ladder's skill-vs-prose call had no empirical feedback: a skill whose
// trigger never fires looked exactly like one that fires daily. This task counts
// loads — and the DENOMINATORS that make a count mean something — out of the logs
// this repo already captures, into a small tracked aggregate.
//
// It also counts what the MACHINERY did: how often the scheduler and the executor
// ran, how many of those hours a session actually opened, what each closed work item
// came to, and what landed in git. That half exists in a repo whose sessions are all
// unattended and captured nothing at all.
//
// WHY DAILY. The file is the whole past-data plane the dashboard renders from
// (claudinite-dashboard) — every panel that reaches further back than one page of live reads
// comes from here. It folded hourly until the scheduler's cron went to two ticks a day
// (tasks-dispatch DESIGN §17): a frequency finer than the cron cannot be honoured, since the
// anchor is only ever seen when a tick comes. Nothing about the DATA changes — hour rows are
// still recomputed from source across a three-day window, so only the newest rows' freshness
// moves, and the dashboard already tops up the freshest hours from the live run listing it
// fetches anyway. The precondition is what keeps a quiet repo quiet.
//
// Self-contained (imports nothing): the whole contract is this default export.

// The signal window a task is judged over: its own period plus the scheduler's hour of slack. A
// log stamped inside it is a session that ran since the last fold. This MUST track the declared
// frequency — sized to an hour while the task anchors daily, the "a session captured" arm never
// fires (a log is ~23h old by the next anchor) and a repo whose only movement is commit-less
// sessions silently stops folding altogether.
const WINDOW_DAYS = 25 / 24;

export default {
  id: 'usage-fold',
  frequency: 'daily',                    // see "WHY DAILY" in the header
  precondition_signals: ['commits', 'conversationLogs'],
  agent_model: 'none',                   // pure code — no agent (task-code-work DESIGN §4)
  expected_outcome: 'pr',
  // The regenerated aggregate is the whole delivery — scoped to the tree it
  // lands in, so a GENERATED file elsewhere in the repo is some other task's.
  // Its merge=ours line is seeded at adoption.
  automerge: ['under:.claudinite/local && generated-file-changes'],
  code_work: 'node worker.mjs',
  // One tree read plus one blob read per capture file in the ~10-day window, all
  // local git, then four REST reads and one PR. A busy repo captures a few files a
  // day, so this is seconds; 600s is ~100x that, generous enough that a huge backlog
  // on a first fold still completes while a hung run is killed well inside the hourly
  // cadence.
  code_work_timeout: 600,

  // Gated on the repo having MOVED this hour, which is the whole difference between an
  // hourly fold and an hourly PR. Two movements are visible to a collector and both
  // change the numbers: a commit on the default branch (the git series, and whatever
  // landed with it), and a conversation log stamped inside the window (a session ran).
  //
  // Deliberately NOT gated on the scheduler having run: it runs every hour by
  // definition, so that gate would be no gate at all. Its runs are not lost by
  // declining — they sit past the watermark and the next fold that does run reads
  // them, and the dashboard tops up the freshest hours from the live run listing it
  // already fetches.
  precondition(signals) {
    const commits = signals.commits ?? {};
    const logs = signals.conversationLogs ?? {};
    const moved = [];
    if (commits.count > 0) moved.push(`${commits.count} commit(s) on the default branch`);
    // `newestLogAgeDays` is null when the branch does not exist or carries no readable
    // stamp — unknown, which is not movement.
    if (logs.newestLogAgeDays !== null && logs.newestLogAgeDays !== undefined && logs.newestLogAgeDays <= WINDOW_DAYS) {
      moved.push('a session captured');
    }
    if (!moved.length) {
      return {
        run: false,
        reason: 'nothing moved this period — no commit on the default branch and no new conversation log; '
          + 'the run and queue reads stay past their watermarks for the next fold that has something to do',
      };
    }
    return { run: true, reason: `fold ${moved.join(' and ')} into the usage aggregate` };
  },
};

// The coded production-validation task (#1530). A verification issue that names
// this task (`Task: claudinite-tasks/verify-production`) carries declarative URL
// probes; the worker fetches and judges them as code-work — Action-side, where
// egress exists — so no agent session is ever spent, and no egress wall is ever
// hit. The grammar and the verdict flow are the worker's (see README.md beside
// it); the filing form is the basics pack's verify-in-production skill.
//
// Self-contained (imports nothing): the whole contract is this default export.

export default {
  id: 'verify-production',
  // MANUAL: an item exists only because a verification was filed and marked —
  // there is nothing to put on a calendar.
  frequency: 'manual',
  precondition_signals: [],
  agent_model: 'none',                   // the whole point: pure code, no session
  expected_outcome: 'none',              // comments and a possible reopen, never a PR
  code_work: 'node worker.mjs',
  // A handful of bounded HTTP fetches plus a few issue writes — minutes at most.
  code_work_timeout: 600,

  // Unconditional: adoption already gated who may route an issue here (the
  // `Task:` field is honoured only for an author with push access), and every
  // later fork — unreadable spec, not yet live, pass, fail — is the run's own
  // verdict, not a reason to skip it.
  precondition() {
    return { run: true, reason: 'a filed production verification is its own mandate' };
  },
};

// basics task: ci-performance — the weekly read on where this repo's CI time goes,
// and whether it has got worse.
//
// A suite's runtime degrades the way a lawn grows: never in one visible step, so
// nobody profiles it until it is bad enough to complain about, by which point the
// cause is a dozen changes back. This task takes the measurement on a cadence
// instead, from the one ledger that cannot be argued with — the Actions run
// history — and keeps a standing record of it.
//
// CONDITIONAL HANDOFF. Code-work does the measuring, which is pure code: read the
// runs, take each workflow's median over this window and the one before, compare.
// A quiet week ends there — the record is refreshed and no agent is spent. Only a
// real regression requests the agent, which then has something worth its time: a
// named workflow, a before and after, and the ci-performance-evaluation skill's
// method for finding the cause.
//
// WHY sonnet: the finding arrives already localized to a workflow and a delta, and
// the skill states the method step by step; what remains is profiling and a bounded
// fix. Ceilinged at `open-pr`, so a change to how this repo builds or tests always
// lands in front of a reviewer.
//
// Self-contained (imports nothing): the whole contract is this default export.

export default {
  id: 'ci-performance',
  frequency: 'weekly',
  // Movement, not standing state: CI runtime only changes when something lands, so
  // a week with no commits and no PR activity has nothing new to measure — the same
  // runs, the same medians, the same verdict as last week.
  precondition_signals: ['commits', 'prs'],
  agent_model: 'sonnet',
  expected_outcome: 'pr',
  automerge: 'anything',             // CI itself is the gate: a fix that turns anything red cannot merge, and a green one is the point (owner, 2026-08-30)
  agent_instructions: 'task.md',
  code_work: 'node worker.mjs',
  // A couple of hundred run records plus one job breakdown, against this repo's own
  // API. Seconds in practice; the bound is for a rate-limited or wedged read.
  code_work_timeout: 300,
  // Profiling a suite means running it, more than once, in both arms of an A/B.
  agent_execution_timeout: 3600,

  precondition(signals) {
    const commits = signals.commits?.count ?? 0;
    const prs = (signals.prs?.touched ?? []).length;
    if (commits === 0 && prs === 0) {
      return { run: false, reason: 'no commits and no PR activity this week — CI ran on nothing new, so its timings cannot have moved' };
    }
    return { run: true, reason: `${commits} commit(s) and ${prs} touched PR(s) this week — re-measure CI timings and compare against the previous window` };
  },
};

// jwt task: jwt-advisory-watch — the one JWT concern that moves with the
// outside world rather than with this repo's commits. JWT libraries have a
// history of critical vulnerabilities (the alg:none era hit several at once),
// and a repo that never touches its lockfile still becomes vulnerable the day
// an advisory publishes. So the watch is a MONTHLY floor, deliberately
// ungated on repo movement: the trigger lives outside the repo, so there is
// no signal to gate on (contrast tidy-prs, whose verdicts only change when a
// PR moves). Worker: task.md. Assess-only: a run that finds an affected version
// files an issue naming it; a clean run writes nothing at all, and never opens a
// PR or edits a manifest.
//
// Self-contained (imports nothing): the whole contract is this default export.

export default {
  id: 'jwt-advisory-watch',
  frequency: 'monthly',                     // an advisory watch is a floor, not an alert channel
  precondition_signals: [],                 // the trigger is the outside world — nothing repo-side gates it
  agent_model: 'sonnet',                    // version-range vs advisory-range comparison is a judgment call
  expected_outcome: 'none',                 // assess-only: opens an ISSUE for a hit, never a PR
  agent_instructions: 'task.md',
  agent_execution_timeout: 900,             // a handful of manifest reads and advisory lookups

  precondition() {
    return {
      run: true,
      reason: 'JWT library advisories publish on the outside world\'s clock — the monthly sweep runs unconditionally',
      context: ['Check the repo\'s JWT/JOSE libraries against published security advisories (read-only — file an issue for a hit, never change a manifest).'],
    };
  },
};

content.content:
1	// chrome-extension task: store-release — the pack-contributed release
2	// trigger (per-project-scheduling DESIGN §6). STRUCTURAL Stage 2: `model: 'none'`
3	// means the whole decision is code and there is NO agent phase —
4	// the executor runs `worker.mjs` as code-work. This task ABSORBS the
5	// release workflow's own independent 00:30 cron: the workflow becomes push +
6	// workflow_dispatch only, and this task is the one place that fires its daily
7	// leg, so the scheduler stays the repo's only cron (DESIGN §3, decision §11.6).
8	//
9	// Self-contained (imports nothing): the whole contract is this default export.
10	
11	const norm = (v) => String(v ?? '').replace(/^v/, '').trim(); // compare tags/versions modulo a leading 'v'
12	
13	export default {
14	  id: 'store-release',
15	  frequency: 'daily',              // the 04:00 anchor (DESIGN §2) — replaces the workflow's own 00:30 cron
16	  precondition_signals: ['release', 'commits'],
17	  agent_model: 'none',                   // pure code — no agent (task-code-work DESIGN §4)
18	  expected_outcome: 'none',                 // it only TRIGGERS the gated publish workflow; publishing stays behind that workflow's own guards
19	  code_work: 'node worker.mjs',      // the executor runs this as code_work (cwd = this task dir) — DESIGN §3
20	  code_work_timeout: 120,            // the dispatch is a quick REST call; a tight bound (the await-the-run Stage 2 would widen it)
21	
22	  // Detect a deployable change since the last release, entirely in code:
23	  //   (a) the manifest version has advanced past the latest published release
24	  //       (an unreleased bump — the same signal the old run_daily gate used), OR
25	  //   (b) a substantive default-branch commit landed in the window (a real ship).
26	  // Ship-path precision (the daily job's `ship_paths` filter) is NOT re-derived
