// chrome-extension task: store-release — the pack-contributed release
// trigger (per-project-scheduling DESIGN §6). STRUCTURAL Stage 2: `model: 'none'`
// means the whole decision is code and there is NO agent phase —
// the executor runs `worker.mjs` as code-work. This task ABSORBS the
// release workflow's own independent 00:30 cron: the workflow becomes push +
// workflow_dispatch only, and this task is the one place that fires its daily
// leg, so the scheduler stays the repo's only cron (DESIGN §3, decision §11.6).
//
// Self-contained (imports nothing): the whole contract is this default export.

const norm = (v) => String(v ?? '').replace(/^v/, '').trim(); // compare tags/versions modulo a leading 'v'

export default {
  id: 'store-release',
  frequency: 'daily',              // the 04:00 anchor (DESIGN §2) — replaces the workflow's own 00:30 cron
  precondition_signals: ['release', 'commits'],
  agent_model: 'none',                   // pure code — no agent (task-code-work DESIGN §4)
  expected_outcome: 'none',                 // it only TRIGGERS the gated publish workflow; publishing stays behind that workflow's own guards
  code_work: 'node worker.mjs',      // the executor runs this as code_work (cwd = this task dir) — DESIGN §3
  code_work_timeout: 120,            // the dispatch is a quick REST call; a tight bound (the await-the-run Stage 2 would widen it)

  // Detect a deployable change since the last release, entirely in code:
  //   (a) the manifest version has advanced past the latest published release
  //       (an unreleased bump — the same signal the old run_daily gate used), OR
  //   (b) a substantive default-branch commit landed in the window (a real ship).
  // Ship-path precision (the daily job's `ship_paths` filter) is NOT re-derived
  // here — .github/release.config isn't in a precondition's scope — because the
  // dispatched daily workflow does the authoritative shipped-file diff vs the
  // latest release tag and no-ops when nothing shippable moved. So the
  // precondition is the cheap pre-filter; the workflow is the exact gate.
  precondition(signals) {
    const rel = signals.release ?? {};

    // Does this repo publish at all? The pack is fingerprinted on the manifest, so
    // it is active on every extension repo, including the ones that only code one —
    // and the daily leg this task fires is a workflow such a repo does not have.
    // `shipsPipeline` is the same orchestrator-name test the release checks gate on
    // (#1057); null means the collector could not read the checkout, which is not a
    // reason to fire a release.
    if (rel.shipsPipeline !== true) {
      return { run: false, reason: 'this repo does not ship the Chrome Web Store pipeline' };
    }

    const shipped = norm(rel.manifestVersion);
    const released = norm(rel.latestTag);
    const manifestAhead = shipped !== '' && shipped !== released;
    const substantive = signals.commits?.substantiveChange === true;

    if (manifestAhead) {
      return { run: true, reason: released ? `manifest ${shipped} is ahead of released ${released}` : `manifest ${shipped}, no release yet` };
    }
    if (substantive) {
      return { run: true, reason: 'substantive default-branch change in the window — let the daily release workflow diff shipped files' };
    }
    return { run: false, reason: 'manifest matches the latest release and no substantive change in the window' };
  },
};

// claudinite-dashboard task: deploy-oauth-exchange — put the dashboard's sign-in
// endpoint live, and prove the deployed URL answers.
//
// `frequency: 'manual'` — nothing recurring is being asked. The endpoint changes
// when its source changes, when the app's client secret is rotated, or when the set
// of page origins allowed to call it changes; none of those is a cadence, so the
// scheduler never instantiates this and the only way it runs is a work item created
// by hand:
//
//   create-work-item claudinite-dashboard/deploy-oauth-exchange
//
// `agent_model: 'none'` — pure code. Read the endpoint's source out of the mount,
// upload it with its bindings, route it, probe it, report the URL.
//
// Self-contained (imports nothing): the whole contract is this default export.

export default {
  id: 'deploy-oauth-exchange',
  frequency: 'manual',
  precondition_signals: [],
  agent_model: 'none',
  // It writes nothing in this repo. The one edit the deployment implies — naming
  // the minted URL as `exchangeUrl` — is the member's own declaration, and the run
  // reports it rather than making it.
  expected_outcome: 'none',
  code_work: 'node worker.mjs',
  // Three API calls and a probe that waits out route propagation (six attempts,
  // five seconds apart). The bound is that probe's worst case with room around it.
  code_work_timeout: 300,
  // The two real credentials, and only those. CLOUDFLARE_API_TOKEN needs exactly one
  // grant — Account · Workers Scripts · Edit — on the account hosting the endpoint;
  // GITHUB_OAUTH_CLIENT_SECRET is the App's client secret. The client id is public and
  // lives in the declaration; the Cloudflare account id is a repository VARIABLE, which
  // every task's code-work is handed with nothing declared, so listing it here would
  // both misstate it as sensitive and put it in a store it does not need.
  required_secrets: ['CLOUDFLARE_API_TOKEN', 'GITHUB_OAUTH_CLIENT_SECRET'],

  // Never due on its own: an item exists only because somebody created one, and
  // that IS the request. A `false` here would close the operator's own item without
  // running it, with no anchor to roll to.
  precondition() {
    return { run: true, reason: 'a work item for this manual lever exists, which is the request to deploy' };
  },
};

// claudinite-fleet-sheepdog task: fleet-add-missing-packs — get every member declaring the packs it
// is missing. The fourth fleet question, now fully on the FAN-OUT model (#749).
//
// `agent_model: 'none'` — this task runs no agent, HERE. Its first incarnation ended
// in an enforcer-side agent stage that ran adopt-pack against members, and it failed
// in production the first time it ran: the enforcer's executor is (correctly) scoped
// to the enforcer repo alone, and "the enforcer's session is provisioned with the
// fleet" turned out to be an assumption, not a fact. The agentic work moved to where
// the access already is: each member's own adopt-requested-packs task
// (claudinite-growth). This task DISPATCHES — it converges a work-list issue in
// the member and fires that member's scheduler — and the member EXECUTES, with the
// repo checked out, under its own declaration's guards. No agent anywhere needs
// cross-repo access.
//
// TWO WAYS A PACK COMES TO BE MISSING, and the task is PARAMETERISED over them
// rather than split in two, because they differ only in how the work list is made:
//   scan_for_needed_packs=true   nobody has decided anything: fingerprint every
//                                member's shape and SUSPECT what its declaration
//                                does not carry. What the weekly run sends.
//   ADD_PACKS=<ids>              the owner already decided: REQUEST these packs,
//                                with this config and these interview answers, in
//                                these named repos. What a FORCED run sends, through
//                                the item's Context — see worker.mjs for
//                                the full override set and params.mjs for why
//                                neither parameter has a default.
// Both converge the same protocol issues (protocol.mjs) and fire the same
// member-side task.
//
// WHERE THE FLEET REACH COMES FROM: FLEET_GITHUB_TOKEN, the account-spanning PAT —
// with Actions WRITE, because firing another repo's scheduler is an Actions write.
// No session scope, no executor grant: the one credential is the PAT, and the only
// things that cross a repo boundary are an issue and a workflow_dispatch.
//
// Self-contained (imports nothing): the whole contract is this default export.

export default {
  id: 'fleet-add-missing-packs',
  frequency: 'weekly',                   // a repo's shape is slow-moving — the same cadence growth-discover-packs uses for the same reason
  precondition_signals: [],              // no signal — every input is another repo's tree, which no per-repo collector can see
  agent_model: 'none',                   // pure code here: scan/request, converge member issues, fire member schedulers — the AGENT is the member's own
  expected_outcome: 'none',              // it writes issues in MEMBERS and queues their runs; no PR here, ever
  // The weekly run's PARAMETERS, sent explicitly on the command line rather than
  // defaulted inside the worker (params.mjs): the declaration is where a reader looks
  // first to learn what the cadence does, so what the cadence does is written here.
  // `all-covered-members` is a keyword the caller sends, not a fallback the worker
  // assumes — no call site can reach the whole fleet by omission.
  code_work: 'node worker.mjs --scan-for-needed-packs=true --repos=all-covered-members',
  // One tree listing per member plus a bounded handful of content reads per
  // content-reading fingerprint, plus the per-member issue convergence and one
  // dispatch POST per member with findings, all serial with a secondary rate limit.
  // The same 900s the other sweeps carry: ~10x the expected walk.
  code_work_timeout: 900,
  required_secrets: ['FLEET_GITHUB_TOKEN'], // the account-spanning PAT; fleet-token.mjs states the grant

  // Fire weekly unconditionally. Every input lives OUTSIDE this repo — another
  // member's tree, another member's declaration — and no per-repo collector can see
  // any of them, so there is no signal that would tell us in advance whether the
  // answer changed. Cheap to no-op: a fleet that declares what it should converges
  // nothing, fires nobody, and the run is one read-only sweep.
  //
  // A hand-created item runs this precondition too (the queue evaluates it at pick,
  // tasks-dispatch DESIGN §6.4), and it says yes unconditionally — so what makes a
  // forced run different is its Context, not a bypass: the parameters there are what
  // run this task as something other than its weekly self.
  precondition() {
    return { run: true, reason: 'weekly fleet scan for packs a member is missing (no-ops cheaply on a fleet whose members already declare what their shape suspects)' };
  },
};

// claudinite-fleet-sheepdog task: fleet-baseline — the enforcer's MANUAL lever: force every covered
// member (or the ones named) to baseline NOW instead of at its next anchor.
//
// `frequency: 'manual'` — the first task on the non-cadence (#749). It answers no
// recurring question, so the scheduler run never instantiates it; the ONLY way it runs is a
// work item created by hand, optionally carrying its parameters as Context lines:
//
//   create-work-item claudinite-fleet-sheepdog/fleet-baseline
//   --context "REPOS=Alpha Beta"        (optional — omit for every covered member; space-separated)
//   --context "DRY_RUN=true"            (optional — report what would fire, fire nothing)
//   --context "INCLUDE_DORMANT=true"    (optional — dormant members are skipped by default)
//   --context "FOLLOW_MINUTES=30"       (optional — how long to follow members to current)
//
// This replaces the pack's standalone fleet-baseline WORKFLOW (retired 2026-08-11,
// #749). The workflow existed for two reasons that are both gone: its FOLLOW half
// (watch every member to a terminal state — a 45-minute sleep no serialized run
// should hold) is given up, and its typed `workflow_dispatch` inputs are carried by
// the item's Context instead. What the workflow shape COST is what this shape
// recovers: the `.github/` managed copy was the one file the nightly converge could
// not push (#649's withhold-and-hand-to-the-agent path), while a task rides the
// ordinary vendor refresh like everything else.
//
// `agent_model: 'none'` — pure code. The whole pass is the dispatch sweep
// (force-fleet-baseline.mjs, invoked by worker.mjs): enumerate the fleet over the
// PAT, wake each covered member's own `update` item, follow each one until it stamps
// canon's published versions, and report the full roster by OUTCOME (#1293). Nothing
// agentic happens HERE — each member's own converge may hand off to that member's own
// agent, which is the fan-out model's point: the enforcer dispatches, the member
// executes, and no agent anywhere needs cross-repo access.
//
// Self-contained (imports nothing): the whole contract is this default export.

export default {
  id: 'fleet-baseline',
  frequency: 'manual',                   // an operator lever — never due on any cadence, runs only when forced
  precondition_signals: [],              // no signal — nothing recurring to predict
  agent_model: 'none',                   // pure code: enumerate, fire, report (task-code-work DESIGN §4)
  expected_outcome: 'none',              // it queues Actions runs in MEMBERS; it writes nothing here or there
  code_work: 'node worker.mjs',
  // The dispatch half is one enumeration plus a declaration read and one POST per
  // member — under a minute. What sizes this bound is the FOLLOW (#1293): the sweep
  // stays until every dispatched member stamps canon's versions, and a member's own
  // update takes 5–10 minutes end to end. The follow gives up at
  // DEFAULT_FOLLOW_MINUTES (20) and reports what it was still waiting on, so this
  // must sit above that with room for the dispatch walk and the final probe —
  // otherwise the platform kills the run at the bound and the report is never
  // printed, which is the one outcome worse than a slow one.
  code_work_timeout: 1800,
  required_secrets: ['FLEET_GITHUB_TOKEN'], // the account-spanning PAT; fleet-token.mjs states the grant

  // Never due on its own — `manual` means the scheduler run never instantiates this task,
  // so an item exists ONLY because a human created one, and that IS the request.
  // Hence run: true. The queue evaluates this verdict at pick (tasks-dispatch
  // DESIGN §6.4), unlike the slot mechanism where a forced run bypassed it; a
  // no-go here has no anchor to roll to, so it would close the operator's own
  // item `task:obsolete` without running. Answering `false` is how this lever
  // stopped working at the flip.
  precondition() {
    return { run: true, reason: 'a work item for this manual lever exists, which is the request to run it' };
  },
};

// claudinite-fleet-sheepdog task: fleet-pack-seeds — does every member declare the packs this fleet
// standardizes on? `agent_model: 'none'` with `code_work: 'node worker.mjs'`: the whole
// pass is deterministic code the executor runs as code-work — no agent, no dispatch
// issue. The worker calls its sibling, the sweep (check-fleet-pack-seeds.mjs): read
// every covered member's declaration and add the seeds it lacks.
//
// WHY: some packs need a parameter no member can derive, because the answer is a fact
// about the FLEET rather than about that repo. Canon cannot supply it — a bootstrap run
// does not know which fleet it is bootstrapping into — and one fleet's value hardcoded
// in shared code is exactly the coupling packs exist to prevent. The enforcer can: it
// IS the fleet. So this repo's `packSeeds` config lists what its members should
// declare, and the sweep converges that list across them.
//
// IT NAMES NO PACK. Every id comes from this repo's own config; the task and its sweep
// carry the mechanism only. A fleet standardizing on different packs changes its
// config, not this pack.
//
// THE ONE SWEEP IN THIS PACK THAT WRITES. The others report a condition and converge an
// issue for a human; a seed carries no human decision (the fleet already made it, in
// this repo's config), so an issue asking someone to copy it into every member would be
// ceremony around a mechanical edit. Hence `expected_outcome: 'none'`: the write goes to
// OTHER repos, not this one, and the outcome ceiling describes what a task may do to its
// OWN repo — this task opens no PR here at all.
//
// CLASSIFICATION (per-project-scheduling DESIGN §6, the same note the other sweeps
// carry): an ORDINARY PACK TASK, not a fleet mechanism. Its *implementation* reaches
// every repo under the owner over a PAT, but its declaration, scheduling and lifecycle
// are exactly those of any pack task — it is active because this repo declares the
// claudinite-fleet-sheepdog pack, and it runs however this repo's tasks run. Hence no
// `session_scope: 'fleet'` and no `fleet` signal: those describe how a task is WIRED,
// and nothing about this task's wiring is fleet-shaped.
//
// Self-contained (imports nothing): the whole contract is this default export.

export default {
  id: 'fleet-pack-seeds',
  frequency: 'daily',                    // a member becomes writable the moment its nightly converge vendors the pack — daily is what turns that into "the next morning"
  precondition_signals: [],              // no signal — the sweep reads the fleet itself, over the PAT
  agent_model: 'none',                   // pure code — no agent (task-code-work DESIGN §4)
  expected_outcome: 'none',              // it writes to MEMBERS, never to this repo: no PR here, ever
  code_work: 'node worker.mjs',
  // Two or three REST reads per member (declaration, whether each seeded pack is on its
  // disk, and one PUT for the members being written) plus the enumeration, all serial,
  // with a secondary rate limit making it slower still. The same 900s the other sweeps
  // carry, for the same reason: ~10x the expected walk while staying inside the hourly
  // cadence.
  code_work_timeout: 900,
  required_secrets: ['FLEET_GITHUB_TOKEN'], // the account-spanning PAT; fleet-token.mjs states the grant

  // Fire daily unconditionally. Every input lives OUTSIDE this repo — another member's
  // declaration, another member's mount — and no per-repo collector can see either, so
  // there is no signal that would say in advance whether the answer changed. The sweep
  // is cheap to no-op: a fleet whose members already declare its seeds reads each one
  // and writes nothing, and a fleet that seeds nothing stops before the walk.
  precondition() {
    return { run: true, reason: 'daily fleet pack-seed sweep (declares this fleet\'s seeded packs in members that lack them; no-ops on a fleet already converged)' };
  },
};

// claudinite-fleet-sheepdog task: fleet-roster — one walk of the fleet answering the enforcer's two
// standing questions about every repo under the owner (#788):
//
//   is this repo a MEMBER?                        → `fleet-adoption` issues
//   is that membership still MEANING anything?    → `fleet-drift` issues
//
// `agent_model: 'none'` with `code_work: 'node worker.mjs'`: the whole pass is
// deterministic code the executor runs as code-work — no agent phase.
// The worker calls its sibling, the sweep (check-fleet-roster.mjs), which enumerates
// the fleet once, reads each repo's declaration once, and hands the resulting roster to
// the two issue families (adoption-issues.mjs, drift-issues.mjs).
//
// WHY ONE TASK. These were two — a daily `fleet-census` and a weekly `fleet-freshness`
// — and each carried its own enumeration, its own structural skips and its own
// declaration read per repo. The freshness half's own header said it "takes coverage as
// given" while in fact re-deriving it on another cadence in another process, so the two
// classifications could disagree and did. One walk means one membership verdict per
// repo, one report, and one failure boundary.
//
// WHY DAILY, and what it costs. The freshness question was weekly because drift is
// measured in DAYS and a daily re-ask could not change its answer. Merged, that
// argument buys nothing: the walk runs daily for the coverage question regardless, and
// the alternative — half the task gated on a weekly cadence it computed itself — would
// reimplement dueness, which the engine owns (the scheduler run instantiates a task's item
// when its anchor comes) and which is not a thing a task can ask about from inside
// itself. So the freshness probe now runs daily too: roughly two extra REST
// reads per covered member on the six days that used to be coverage-only. The merge is
// not an API-call saving and is not claimed as one — what it buys is one roster instead
// of two that can disagree. Drift converging within a day rather than a week is the
// side benefit, and convergeDrift's silence on an unchanged verdict is what keeps the
// faster cadence from turning every thread into a wall of identical notes.
//
// CLASSIFICATION (per-project-scheduling DESIGN §6, the same note RULES.md carries):
// this is an ORDINARY PACK TASK, not a fleet mechanism. Its *implementation* happens to
// scan every repo under the owner over a PAT, but its declaration, scheduling and
// lifecycle are exactly those of any pack task — it is active because this repo declares
// the claudinite-fleet-sheepdog pack, and it runs however this repo's tasks run. Hence no `fleet` signal
// and no session scope of its own (the PACK declares the executor reach): those describe
// how a task is WIRED, and nothing about this task's wiring is fleet-shaped. The
// cross-repo reach lives in the implementation, never in the declaration.
//
// Self-contained (imports nothing): the whole contract is this default export.

export default {
  id: 'fleet-roster',
  frequency: 'daily',                    // the coverage question's cadence — a repo created, adopted or archived under the owner should not wait a week
  precondition_signals: [],              // no signal — the sweep reads the fleet itself, over the PAT
  agent_model: 'none',                   // pure code — no agent (task-code-work DESIGN §4)
  expected_outcome: 'none',              // the honest ceiling: it opens ADOPTION and DRIFT issues, never a PR — it reports, it does not repair
  code_work: 'node worker.mjs',
  // The walk covers EVERY repo in the fleet: one paged enumeration, one declaration
  // read per repo, two further reads per measured member (scheduler workflow, canon
  // compare), then both issue convergences — all serial, and a secondary rate limit
  // makes it slower still. The same 900s both predecessors carried: ~10x the expected
  // walk while staying well inside the hourly scheduler cadence, so a hung sweep is
  // killed long before the next run could collide with it.
  code_work_timeout: 900,
  required_secrets: ['FLEET_GITHUB_TOKEN'], // the account-spanning PAT; fleet-token.mjs states the grant

  // Fire daily unconditionally. Every input lives OUTSIDE this repo — another repo's
  // declaration, another member's workflow, canon's head — and no per-repo collector
  // can see any of them, so there is no signal that would tell us in advance whether
  // either answer changed. Cheap to no-op: a converged fleet opens and closes nothing,
  // and an unhealthy member that is unhealthy for the same reason is not even
  // commented on.
  precondition() {
    return { run: true, reason: 'daily fleet roster sweep — coverage and freshness in one walk (converges adoption and drift issues; no-ops cheaply on a converged fleet)' };
  },
};

// growth-discover-packs — the FLEET sweep for technologies the canon does not yet
// home. One weekly pass over every member: read what the fleet is actually built
// on, subtract what the canon's packs/ shelf already homes, and open a reviewed PR
// authoring the missing pack.
//
// The only pack-authoring stage there is. A member does not mint packs of its
// own — its local packs are what adoption seeded, and growth-extract writes
// rules into those — so a technology no canon pack homes is noticed and homed
// here or nowhere.
//
// Central because ONE run sees every member: first-sight dedup is trivial — the
// third member using a technology is recognised as the same gap as the first,
// with no cross-run state. That was the argument for keeping this central when
// everything else moved per-repo.
//
// Self-contained (imports nothing): the whole contract is this default export.

export default {
  id: 'growth-discover-packs',
  frequency: 'weekly',                   // the fleet's stacks are slow-moving — a weekly sweep, not a daily one
  precondition_signals: ['fleet'],       // canon-only aggregate: who the members are and what they declare
  // This task reads every member's tree, which an ordinary session in this repo does
  // not reach. Reach is a property of WHICH endpoint the hand-off calls, so a task
  // needing more than an ordinary session names one; the key resolves in this repo's
  // own config, and until it is configured the hand-off converges the item to triage
  // naming what is missing.
  invocation_endpoint: 'fleet',
  agent_model: 'opus',                   // judging what is genuinely canon-worthy and authoring a pack is heavy judgment
  expected_outcome: 'pr',
  automerge: 'nothing',              // a new canon pack every repo will read — owner-approved, never auto-merged
  agent_instructions: 'task.md',
  agent_execution_timeout: 3600,         // manifest N members' stacks + author a pack — a generous weekly bound, extreme protection

  // Fire on the covered members, every week. There is no windowed trigger: the
  // opportunity is standing (a technology the fleet uses that no canon pack
  // homes), not a recent change, so the sweep runs weekly and no-ops cheaply
  // when nothing is unhomed. A member with a parsable declaration but no declared
  // packs is not running Claudinite in any usable sense — the same test the fleet
  // reader uses before it probes a member — so it is not swept.
  precondition(signals) {
    const fleet = signals.fleet;
    if (!fleet) return { run: false, reason: 'no fleet signal (FLEET_GITHUB_TOKEN unset, or this repo is not a canon home)' };
    if (fleet.error) return { run: false, reason: `fleet enumeration failed — ${fleet.error} (sweeping nothing on unproven fleet state)` };
    const members = (fleet.members ?? []).filter((m) => m.activePacks.length);
    if (!members.length) return { run: false, reason: 'no covered member to sweep' };
    const repos = members.map((m) => m.repo);
    return {
      run: true,
      reason: `weekly canon pack-discovery sweep over ${members.length} covered member(s)`,
      context: [
        `Members to sweep: ${repos.join(', ')}.`,
        'Read ONLY these members — do not enumerate the fleet yourself or widen past this list.',
      ],
    };
  },
};

// growth-promote — the growth lifecycle's CENTRAL stage. Reads the participating
// members' local packs, generalizes the portable lessons, and opens an owner-gated
// PR against the canon. A fleet-reaching task: it runs on the canon home repo's own
// scheduler, and its precondition reads the `fleet` signal — the members aggregate
// over the fleet PAT.
//
// Self-contained (imports nothing): the whole contract is this default export.
//
// "Central, once" is enforced by declaration cardinality, not orchestrator wiring:
// a canon is declared by its one home repo, so this task exists nowhere else. No
// barrier — promote reads whatever is already MERGED on members' default branches,
// so a lesson extracted tonight is promoted on the same run when its auto-merge
// landed in time, else the next one.

export default {
  id: 'growth-promote',
  frequency: 'daily',
  // THE CROSS-REPO HALF IS THIS REPO'S OWN scheduler anchor, not a field here. Promote reads what
  // has already merged on MEMBERS' default branches, and `schedule_after:` only ever matches an item
  // in this repo's own queue — so the members-extract-then-canon-promotes ordering has no declarable
  // form and lives in the anchor: a canon home sets its daily hour after its members'.
  //
  // The WITHIN-repo half is declarable, and is: a canon home is a member too, so its own extract must
  // settle before promote reads the local packs it just wrote. A canon that does not declare
  // claudinite-growth queues no such item, and the ordering is then vacuous rather than blocking.
  schedule_after: ['claudinite-growth/growth-extract'],
  precondition_signals: ['fleet'],       // canon-only aggregate: which members changed their local packs
  // This task reads every member's local packs, which an ordinary session in this
  // repo does not reach. Reach is a property of WHICH endpoint the hand-off calls,
  // so a task needing more than an ordinary session names one; the key resolves in
  // this repo's own config, and until it is configured the hand-off converges the
  // item to triage naming what is missing.
  invocation_endpoint: 'fleet',
  agent_model: 'opus',                   // portability, dedup-vs-corpus, and routing are the heaviest judgment
  expected_outcome: 'pr',
  automerge: 'nothing',              // the judgment gate before shared canon — owner-approved, never auto-merged
  agent_instructions: 'task.md',
  agent_execution_timeout: 2700,         // reading N members + generalizing + authoring a PR — generous bound, extreme protection

  // Fire when a participating member changed its local packs in the window. A
  // participant declares claudinite-growth and carries local packs (the only
  // source promote reads); the growth entry's `{ config: { promote: false } }`
  // opts a member out of promotion while it keeps extracting/deduping locally
  // (absent or true = participate). A member whose local packs didn't move in the
  // window has nothing new to lift up — so the daily trigger targets exactly the
  // changed set, and the executor's Context binds the worker to those members.
  precondition(signals) {
    const fleet = signals.fleet;
    if (!fleet) return { run: false, reason: 'no fleet signal (FLEET_GITHUB_TOKEN unset, or this repo is not a canon home)' };
    if (fleet.error) return { run: false, reason: `fleet enumeration failed — ${fleet.error} (retiring/promoting nothing on unproven fleet state)` };
    const participants = (fleet.members ?? [])
      .filter((m) => m.activePacks.includes('claudinite-growth') && m.hasLocalPacks)
      .filter((m) => m.packConfigs?.['claudinite-growth']?.promote !== false);
    const changed = participants.filter((m) => m.localPacksChanged);
    if (!changed.length) return { run: false, reason: 'no participating member changed its local packs in the window' };
    const repos = changed.map((m) => m.repo);
    return {
      run: true,
      reason: `${changed.length} participating member(s) changed their local packs in the window`,
      context: [
        `Target members (local packs changed in the window): ${repos.join(', ')}.`,
        'Read ONLY these members\' local packs — do not enumerate the fleet yourself or widen past this list.',
      ],
    };
  },
};

// The request implementer (tasks-dispatch DESIGN §16) — the engine's one built-in
// task, and the only one that may read an item's `Model`.
//
// A person marks an ordinary issue `task:origin:ad-hoc`; the scheduler run adopts
// it by writing the machine block onto that issue and applying the first status —
// the issue IS the item (§16.1); this task's precondition decides, at pickup,
// whether the run happens; the session implements the issue and leaves a pull
// request. There is no code-work phase at all: the authorization a worker would
// have performed is the precondition's, and the item's `Request:` field — which
// names the item's own issue — is the whole payload.

// Push permission, as the permission API answers it. `triage` and `read` are
// deliberately not here: the ask was push access, and a read-only collaborator
// rides every webhook payload as `COLLABORATOR` (F30).
export const PUSH_PERMISSIONS = ['admin', 'maintain', 'write'];

// Who, if anyone, with push access asked for this. Pure over the `request` signal's
// read, so the judgment is testable without GitHub and the reads stay where every
// other read is.
export function eligibility(req) {
  if (PUSH_PERMISSIONS.includes(req.authorPermission)) {
    return { ok: true, why: `opened by @${req.author}, who has push access` };
  }
  const blessed = (req.approvals ?? []).find((a) => PUSH_PERMISSIONS.includes(a.permission));
  if (blessed) return { ok: true, why: `approved by @${blessed.login} with \`/claude go\`` };
  return { ok: false, why: 'neither opened nor approved with `/claude go` by anyone with push access on this repository' };
}

export default {
  // The literal, not the constant beside it in `built-in-tasks.mjs`: the
  // declaration-shape check reads this file statically and cannot resolve an
  // import. The two are pinned to each other in request-mode.test.mjs.
  id: 'implement-request',
  // MANUAL: the scheduler run never puts this on a calendar. An item exists only because an
  // issue was marked, which is what makes a request a first-class origin of work
  // rather than a schedule nobody asked for.
  frequency: 'manual',
  // The read the precondition judges on. It is collected for THIS item — the issue
  // its `Request:` field names — which is why the precondition takes the item.
  precondition_signals: ['request'],
  // The default when the asker named no family; the item's `Model:` overrides it,
  // and only because this task declares the field below.
  agent_model: 'opus',
  model_from_request: true,
  // The ceiling the executor enforces in code. The task's own policy is the full
  // `anything` because the REAL decider is per-request: the asker's `Automerge:`
  // becomes the item's `Merge:` field (§16.11), a policy expression the worker
  // hands to the policy engine, and the task ceiling must not sit below whatever
  // an asker may legitimately authorize. A ceiling is a maximum, not an
  // instruction: with no such field the worker opens a pull request and parks at
  // the approval lane exactly as every request did before, and with one it still
  // parks whenever the policy engine says the diff is not covered.
  expected_outcome: 'pr',
  automerge: 'anything',
  agent_instructions: 'task.md',
  agent_execution_timeout: 4 * 3600,
  // A run that died mid-flight leaves a branch, a PR, or neither, and only a person
  // can say whether the half-done work stands — so nothing re-queues it mechanically.
  on_interrupt: 'needs-human',

  // THE SECURITY CHECK, and it happens where every verdict happens: once, at pickup,
  // on the executor (§6.4). Three refusals, each a plain no-go that converges the
  // item to the rejected terminal — a refusal is nobody's inbox, and an ad-hoc item
  // has no anchor to roll to. On a marked issue that terminal stands on the OPEN
  // issue: the run's verdict is not the issue's validity (§16.5).
  //
  // A READ FAILURE IS NOT A VERDICT (F27). The decline's write-back cannot reach an
  // issue it cannot read, so declining on a rate limit or a 500 would strand
  // `claude-queued` on the issue forever over nothing — the request silently eaten.
  // Only a definitive `gone` declines; anything else FAILS the run, which parks the
  // item open in the failure lane where the ordinary re-queue lever retries it.
  precondition(signals, config, item) {
    const req = signals.request;
    if (!req) {
      return { error: `this item names no readable request (its \`Request:\` field is ${item?.request ? `#${item.request}` : 'missing'})` };
    }
    if (req.unreadable) return { error: `issue #${req.number} could not be read: ${req.error} — refusing to guess` };
    if (req.gone) return { run: false, reason: `issue #${req.number} does not exist` };
    if (req.state !== 'open') return { run: false, reason: `issue #${req.number} was closed before this ran` };
    if (!req.queued) {
      return { run: false, reason: `issue #${req.number} no longer carries the mark — the request was withdrawn` };
    }
    const verdict = eligibility(req);
    return verdict.ok
      // No `context`: adoption already bound this item to its issue, and a second
      // line saying the same thing renders as two near-identical bullets in the one
      // section the session is told to read as its scope (seen on the first live
      // request, #1074/#1075).
      ? { run: true, reason: `#${req.number}: ${verdict.why}` }
      : { run: false, reason: `#${req.number}: ${verdict.why}` };
  },
};

