66	async function paged(gh, path, maxPages = Infinity) {
67	  const out = [];
68	  for (let page = 1; page <= maxPages; page += 1) {
69	    const sep = path.includes('?') ? '&' : '?';
70	    const { status, json } = await gh(`${path}${sep}per_page=100&page=${page}`);
71	    if (status !== 200 || !Array.isArray(json) || json.length === 0) break;
72	    out.push(...json);
73	    if (json.length < 100) break;
74	  }
75	  return out;
76	}
77	
78	// Like `paged`, but for a listing sorted `updated` DESCENDING and bounded by the
79	// window: it stops at the first item outside it and does not fetch the next page.
80	// The closed-PR listing is otherwise the repo's whole history — a window read must
81	// not cost proportionally to that.
82	async function pagedWindow(gh, path, inWindow) {
83	  const out = [];
84	  for (let page = 1; ; page += 1) {
85	    const sep = path.includes('?') ? '&' : '?';
86	    const { status, json } = await gh(`${path}${sep}per_page=100&page=${page}`);
87	    if (status !== 200 || !Array.isArray(json) || json.length === 0) break;
88	    const kept = [];
89	    for (const item of json) {
90	      if (!inWindow(item)) break;
91	      kept.push(item);
92	    }
93	    out.push(...kept);
94	    if (kept.length < json.length || json.length < 100) break;
95	  }
96	  return out;
97	}
