99	// A merged PR is mineable unless it is bot work or one of Claudinite's own
100	// automated writes — the same author/message exclusions `isSubstantive` and the
101	// `issues` collector apply, kept together on purpose. It does NOT carry the
102	// corpus-only exclusion: the PR listing has no file list, and resolving one per
103	// PR would cost a read per PR across the whole window. It does not need to —
104	// a corpus-only PR's merge commit is already non-substantive, so no task with a
105	// `commits`-gated precondition ever reaches this listing on its account. The housekeeping regex already covers
106	// the growth tasks' own `Claudinite growth: …` PRs and the scheduler's
107	// `[claudinite-task]` titles, so the self-trigger guards survive the widening.
108	// How far the per-open-PR file read pages before it stops (100 files a page).
109	const PR_FILE_PAGES = 3;
110	
111	const isMinablePr = (p) => {
112	  if ((p.user?.login ?? '').endsWith('[bot]')) return false;
113	  return !HOUSEKEEPING.test((p.title ?? '').trim());
114	};
115	
116	// Commit objects in the window, with their changed-file lists resolved (one read
117	// per commit — the window is a handful of commits).
118	async function windowCommits(gh, repo, branch, sinceIso) {
119	  const list = await paged(gh, `/repos/${repo}/commits?sha=${encodeURIComponent(branch)}&since=${sinceIso}`);
120	  const detailed = [];
121	  for (const c of list) {
122	    const d = await gh(`/repos/${repo}/commits/${c.sha}`);
123	    const files = d.status === 200 ? (d.json?.files ?? []).map((f) => f.filename).filter(Boolean) : [];
124	    detailed.push({ sha: c.sha, message: c.commit?.message ?? '', author: c.author?.login ?? null, substantive: isSubstantive(c, files), files });
125	  }
126	  return detailed;
127	}
