129	const COLLECTORS = {
130	  async commits(gh, ctx) {
131	    const commits = await windowCommits(gh, ctx.repo, ctx.defaultBranch, ctx.sinceIso);
132	    return {
133	      list: commits,
134	      count: commits.length,
135	      substantiveChange: commits.some((c) => c.substantive),
136	      touchedPaths: [...new Set(commits.flatMap((c) => c.files))],
137	    };
138	  },
139	
140	  async prs(gh, ctx) {
141	    const open = await paged(gh, `/repos/${ctx.repo}/pulls?state=open&sort=updated&direction=desc`);
142	    const since = new Date(ctx.sinceIso);
143	
144	    // PRs MERGED during the window, in a field of their OWN. A merged PR carries
145	    // the review discussion and the "what changed and why" — usually the richest
146	    // lesson material in a window — and `state=open` alone made it unreachable to
147	    // any task bound to this signal. It is deliberately NOT folded into `open` or
148	    // `touched`: those two are other tasks' target sets (the PR tidy sweep acts on
149	    // `open`), and widening them here would silently widen what those tasks do.
150	    // The same exclusions the `commits` and `issues` collectors apply hold here, so
151	    // a growth task still cannot see its own merged output and re-trigger on it.
152	    const closed = await pagedWindow(
153	      gh,
154	      `/repos/${ctx.repo}/pulls?state=closed&sort=updated&direction=desc`,
155	      (p) => new Date(p.updated_at) >= since,
156	    );
157	    const merged = closed
158	      .filter((p) => p.merged_at && new Date(p.merged_at) >= since && isMinablePr(p))
159	      .map((p) => ({ number: p.number, title: p.title, mergedAt: p.merged_at }));
160	
161	    // Each open PR's changed paths — the pending work itself, so a precondition
162	    // can rule on WHAT is waiting for review rather than on a marker somebody has
163	    // to remember to apply (wiki-growth declines while a `product-wiki/` change is
164	    // pending). One read per open PR: the open set is a handful, and no PR listing
165	    // carries files.
166	    //
167	    // `null` is UNKNOWN, and it is a third state, not an empty list: every PR
168	    // changes at least one file, so an empty read is a read that failed, and a
169	    // precondition gating on a path must decline on "I could not look" rather than
170	    // read it as "nothing pending".
171	    const withPaths = [];
172	    for (const p of open) {
173	      // Capped at PR_FILE_PAGES: past it a PR is a mass refactor, whose paths no
174	      // consumer of this signal rules on, and paying 30 reads for one would be the
175	      // window's whole budget.
176	      const files = await paged(gh, `/repos/${ctx.repo}/pulls/${p.number}/files`, PR_FILE_PAGES);
177	      const changedPaths = files.map((f) => f.filename).filter(Boolean);
178	      withPaths.push({
179	        number: p.number, title: p.title, updatedAt: p.updated_at,
180	        changedPaths: changedPaths.length ? changedPaths : null,
181	      });
182	    }
183	
184	    return {
185	      open: withPaths,
186	      touched: open.filter((p) => new Date(p.updated_at) >= since).map((p) => p.number),
187	      merged,
188	    };
189	  },
