191	  async issues(gh, ctx) {
192	    const open = await paged(gh, `/repos/${ctx.repo}/issues?state=open&sort=updated&direction=desc`);
193	    const since = new Date(ctx.sinceIso);
194	    // Exclude PRs (the issues endpoint returns both) and the scheduler's own
195	    // work items, its schedule board, and standing trackers — invisible to
196	    // signals (DESIGN §3.3). The board especially: every rewrite would land in
197	    // `issues.touched` and wake tidy-issues on the queue's own churn (F8).
198	    const real = open.filter((i) => !i.pull_request
199	      && !/^\[claudinite-(task|work|schedule)\]/.test(i.title ?? '')
200	      && !/^(claudinite tracker:|\[claudinite\] ci performance$|auto-improvements tracker\b|repo tidy tracker$)/i.test((i.title ?? '').trim()));
201	    return {
202	      open: real.map((i) => ({ number: i.number, title: i.title, updatedAt: i.updated_at, labels: (i.labels ?? []).map((l) => l.name ?? l) })),
203	      touched: real.filter((i) => new Date(i.updated_at) >= since).map((i) => i.number),
204	    };
205	  },
206	
207	  // Every open branch, each with the date of its tip commit — so a precondition
208	  // can tell a branch that MOVED in the window from the standing pile that did
209	  // not. `touched` is the same field name, with the same meaning, the `prs` and
210	  // `issues` collectors carry; without it the branch dimension had no notion of
211	  // newness at all and every gate over it degenerated to "a branch exists".
212	  //
213	  // The tip date costs one commit read per DISTINCT tip sha (branches sharing a
214	  // tip share the read) because the branch listing carries no date of its own —
215	  // no REST listing does. That is the price of the only newness this dimension
216	  // can observe, and it is paid on a weekly clock over a handful of branches.
217	  // A tip read that fails leaves `updatedAt: null`, which is NOT touched: no
218	  // proof of movement never wakes an agent.
219	  async branches(gh, ctx) {
220	    const list = await paged(gh, `/repos/${ctx.repo}/branches`);
221	    const since = new Date(ctx.sinceIso);
222	
223	    const dateBySha = new Map();
224	    for (const sha of new Set(list.map((b) => b.commit?.sha).filter(Boolean))) {
225	      const { status, json } = await gh(`/repos/${ctx.repo}/commits/${sha}`);
226	      const c = status === 200 ? json?.commit : null;
227	      dateBySha.set(sha, c?.committer?.date ?? c?.author?.date ?? null);
228	    }
229	
230	    const entries = list.map((b) => ({ name: b.name, updatedAt: dateBySha.get(b.commit?.sha) ?? null }));
231	    return {
232	      names: entries.map((e) => e.name),
233	      list: entries,
234	      touched: entries.filter((e) => e.updatedAt && new Date(e.updatedAt) >= since).map((e) => e.name),
235	    };
236	  },
237	
238	  async release(gh, ctx) {
239	    const { status, json } = await gh(`/repos/${ctx.repo}/releases/latest`);
240	    const latestTag = status === 200 ? (json?.tag_name ?? null) : null; // 404 → no release yet
241	    return { latestTag, manifestVersion: ctx.manifestVersion ?? null, shipsPipeline: ctx.shipsReleasePipeline ?? null };
242	  },
243	
244	  // Whether the repo carries local packs, and whether a window commit touched
245	  // one (under either local root during the rename window).
246	  async localPacks(gh, ctx) {
247	    const commits = ctx.commits ?? await windowCommits(gh, ctx.repo, ctx.defaultBranch, ctx.sinceIso);
248	    const touches = (f) => LOCAL_PACK_ROOTS.some((r) => f.startsWith(r));
