253	  // Which DECLARED packs' vendored files changed in the window — the local echo
254	  // of "canon changed" (replaces the cross-repo relevantCanonChanged).
255	  async sharedMount(gh, ctx) {
256	    const commits = ctx.commits ?? await windowCommits(gh, ctx.repo, ctx.defaultBranch, ctx.sinceIso);
257	    const declared = new Set(ctx.activePacks ?? []);
258	    const changed = new Set();
259	    for (const c of commits) {
260	      for (const f of c.files) {
261	        const m = /^\.claudinite\/shared\/packs\/([^/]+)\//.exec(f);
262	        if (m && declared.has(m[1])) changed.add(m[1]);
263	      }
264	    }
265	    return { changedPacks: [...changed] };
266	  },
