268	  // The conversation-logs orphan branch: present, and the age of its oldest JSONL
269	  // vs the configured retention (the age-based prune's trigger on quiet repos).
270	  //
271	  // Age comes from the FILENAME stamp, not from git/commit metadata. Commit dates
272	  // are the authoritative record of when a blob landed, but they are the wrong
273	  // authority here and cost more: (a) AGREEMENT — the consuming task's prune rule
274	  // is itself stated over the filename stamp ("each log whose filename stamp is
275	  // older than retention"), so a commit-date trigger would dispatch an agent over
276	  // logs the worker then declines to prune, and stay silent on ones it would
277	  // prune; (b) COST — one tree
278	  // read covers the whole branch, against one commit-history read per file, and
279	  // the branch accumulates one log per merged session. The name is machine-written
280	  // by the pack's capture step, never user input, so "trusting the name" is
281	  // trusting our own writer — and a drift guard pins the two formats together.
282	  async conversationLogs(gh, ctx) {
283	    const retentionDays = ctx.retentionDays ?? null;
284	    const branch = await gh(`/repos/${ctx.repo}/branches/conversation-logs`);
285	    if (branch.status !== 200) {
286	      return { present: false, retentionDays, oldestLogAgeDays: null, newestLogAgeDays: null, logCount: 0 };
287	    }
288	
289	    // Logs sit flat at the branch root beside its README; a non-200 tree read (or
290	    // anything unparsable on it) is "no age to judge", never a failed collection.
291	    const { status, json } = await gh(`/repos/${ctx.repo}/git/trees/conversation-logs`);
292	    const stamps = (status === 200 && Array.isArray(json?.tree) ? json.tree : [])
293	      .map((e) => logStampMs(e?.path ?? ''))
294	      .filter((ms) => ms !== null);
295	    const now = new Date(ctx.now).getTime();
296	    const age = (ms) => (stamps.length && Number.isFinite(now) ? (now - ms) / 86400000 : null);
297	    // Both ends, because they answer opposite questions. The OLDEST drives the
298	    // age-based prune (is anything past retention). The NEWEST is the only NEWNESS
299	    // this dimension has: "did a session capture in the window", which is what a
300	    // precondition gated on repo movement needs and which a total count — true
301	    // forever once true — cannot say.
302	    return {
303	      present: true,
304	      retentionDays,
305	      oldestLogAgeDays: stamps.length ? age(Math.min(...stamps)) : null,
306	      newestLogAgeDays: stamps.length ? age(Math.max(...stamps)) : null,
307	      logCount: stamps.length,
308	    };
309	  },
