311	  // WHAT THE MOUNT HOLDS, and whether it moved in this window: the installed engine
312	  // version, the installed pack versions, and whether any `.claudinite/shared/**`
313	  // file was touched by a commit in the window.
314	  //
315	  // `convergedInWindow` is what replaced the stamp's age (#1252). The age came off a
316	  // datetime that recorded the last FULL re-vendor rather than the last converge, so
317	  // it read months stale on a member converging nightly — and newness taken from the
318	  // objects' OWN movement in the window is where every other precondition here gets
319	  // it. `present` is the mount's existence, which the versions answer directly: an
320	  // engine that stamps always stamps.
321	  async stamp(gh, ctx) {
322	    const commits = ctx.commits ?? await windowCommits(gh, ctx.repo, ctx.defaultBranch, ctx.sinceIso);
323	    const convergedInWindow = commits.some((c) => c.files.some((f) => f.startsWith(`${SHARED_SUBDIR}/`)));
324	    return {
325	      present: (ctx.config?.engineVersion ?? null) !== null || Object.keys(ctx.config?.packVersions ?? {}).length > 0,
326	      engineVersion: ctx.config?.engineVersion ?? null,
327	      packVersions: ctx.config?.packVersions ?? {},
328	      convergedInWindow,
329	      canonHead: ctx.canonHead ?? null,
330	    };
331	  },
