333	  // Fleet aggregate — canon-only, over the fleet PAT (DESIGN §3.3). A consumer
334	  // cannot declare it; the collector returns null unless the caller supplied a
335	  // fleet reader (wired on the canon and fleet-enforcer repos in Phase 2).
336	  // THE REQUEST READ (tasks-dispatch DESIGN §16.4). Unlike every collector beside
337	  // it, this one reads a single named object rather than a window: the issue THIS
338	  // item was created for, off `ctx.item.request`. That is what the precondition's
339	  // third argument buys — a verdict about one issue, which no window of repo
340	  // activity can single out.
341	  //
342	  // It reads facts and forms no judgment: who asked, who blessed it with the
343	  // approval phrase, and what PERMISSION each of them holds — never whether that is
344	  // enough. The rule lives in the task's precondition, where every other verdict is.
345	  //
346	  // Three shapes of answer, and the difference between the last two is the whole of
347	  // F27: `gone` (the API says it does not exist) is a fact a precondition can
348	  // decline on, while `unreadable` (a rate limit, a 500) is one it must NOT — a
349	  // decline's write-back cannot reach an issue it cannot read.
350	  async request(gh, ctx) {
351	    const number = ctx.item?.request ?? null;
352	    if (!number) return null;
353	    const { status, json } = await gh(`/repos/${ctx.repo}/issues/${number}`);
354	    if (status === 404 || status === 410) return { number, gone: true };
355	    if (status !== 200 || !json) return { number, unreadable: true, error: `the issues API answered ${status}` };
356	
357	    // The permission API is the authority, never the payload's `author_association`:
358	    // `MEMBER` is any org member whatever their repo permission, and `COLLABORATOR`
359	    // includes read-only collaborators — both broader than push (F30). A read that
360	    // fails is unreadable, not "no permission": guessing downward here would refuse
361	    // a legitimate request over a rate limit.
362	    const permissions = new Map();
363	    let failed = null;
364	    const permissionOf = async (login) => {
365	      if (!login) return 'none';
366	      if (permissions.has(login)) return permissions.get(login);
367	      const res = await gh(`/repos/${ctx.repo}/collaborators/${encodeURIComponent(login)}/permission`);
368	      // A 403/404 here is a real answer: the caller may not read collaborators, or
369	      // this login is not one. The first is a repo-configuration fault and the
370	      // second is the ordinary "a stranger opened it" case, and only the API can
371	      // tell them apart — so a 404 is `none` and anything else stops the read.
372	      let value;
373	      if (res.status === 200) value = res.json?.role_name ?? res.json?.permission ?? 'none';
374	      else if (res.status === 404) value = 'none';
375	      else { failed = `the permission API answered ${res.status} for @${login}`; value = 'none'; }
376	      permissions.set(login, value);
377	      return value;
378	    };
379	
380	    const author = json.user?.login ?? null;
381	    const authorPermission = await permissionOf(author);
382	    // The approval phrase is only worth a permission read on the comments that
383	    // carry it, so an issue with a long thread costs one read per distinct blesser.
384	    const comments = await paged(gh, `/repos/${ctx.repo}/issues/${number}/comments`);
385	    const approvals = [];
386	    for (const c of comments) {
387	      const login = c.user?.login ?? null;
388	      if (!login || !APPROVAL_RE.test(c.body ?? '')) continue;
389	      approvals.push({ login, permission: await permissionOf(login) });
390	    }
391	    if (failed) return { number, unreadable: true, error: failed };
392	
393	    return {
394	      number,
395	      state: json.state,
396	      labels: (json.labels ?? []).map((l) => l.name ?? l),
397	      // STILL MARKED, in any spelling this repo's issues may carry: the origin the
398	      // one-issue model applies, and the two retired `claude-*` labels a shadow item's
399	      // issue wears. Withdrawing is removing what marked it, whichever that was.
400	      queued: (json.labels ?? []).map((l) => l.name ?? l)
