403	      authorPermission,
404	      approvals,
405	    };
406	  },
407	
408	  async fleet(gh, ctx) {
409	    return ctx.fleet ?? null;
410	  },
411	};
412	
413	export const SIGNAL_COLLECTORS = Object.keys(COLLECTORS);
414	
415	// Collect exactly the requested signal names into one object. An unknown name is
416	// ignored (the task-declaration-shape check rejects those at author time); a
417	// collector that throws records `{ error }` under its key rather than sinking the
418	// whole collection (per-signal isolation).
419	export async function collectSignals(gh, ctx, names) {
420	  const out = {};
421	  // Commit-derived collectors share one window read.
422	  if (names.some((n) => ['commits', 'localPacks', 'sharedMount', 'stamp'].includes(n)) && !ctx.commits) {
423	    try { ctx = { ...ctx, commits: await windowCommits(gh, ctx.repo, ctx.defaultBranch, ctx.sinceIso) }; } catch { /* collectors re-read on demand */ }
424	  }
425	  for (const name of names) {
426	    const collect = COLLECTORS[name];
427	    if (!collect) continue;
428	    try { out[name] = await collect(gh, ctx); }
429	    catch (e) { out[name] = { error: e.message }; }
430	  }
431	  return out;
432	}
