// logs-prune's own precondition term (task-preconditions DESIGN): a named
// predicate over the collected signals, resolved by the evaluator after the
// built-ins. It tests the age, not "a branch exists and retention is
// configured" — that pair is true on every capturing repo every day, and a
// condition that is true forever once true is not a trigger at all.
export const terms = {
  'log-past-retention': {
    signals: ['conversationLogs'],
    holds({ conversationLogs: logs }) {
      if (logs?.present !== true) return { holds: false, reason: 'no conversation-logs branch — nothing captured yet' };
      const { retentionDays: retention, oldestLogAgeDays: oldest } = logs;
      if (typeof retention !== 'number') return { holds: false, reason: 'retention_days is unset — capture-only adoption, the prune deletes nothing' };
      if (!(typeof oldest === 'number' && oldest > retention)) {
        return { holds: false, reason: `no log older than retention ${retention}d — nothing to prune` };
      }
      return { holds: true, reason: `oldest log ${oldest.toFixed(1)}d old vs retention ${retention}d` };
    },
  },
};

