// store-release's own precondition term (task-preconditions DESIGN): an
// unreleased manifest bump, detected entirely in code. Versions compare modulo
// a leading 'v'.
const norm = (v) => String(v ?? '').replace(/^v/, '').trim();

export const terms = {
  'manifest-ahead': {
    signals: ['release'],
    holds({ release: rel }) {
      const shipped = norm(rel?.manifestVersion);
      const released = norm(rel?.latestTag);
      if (shipped === '') return { holds: false, reason: 'no readable manifest version' };
      if (shipped === released) return { holds: false, reason: `manifest ${shipped} matches the latest release` };
      return {
        holds: true,
        reason: released ? `manifest ${shipped} is ahead of released ${released}` : `manifest ${shipped}, no release yet`,
      };
    },
  },
};

