3	// means the whole decision is code and there is NO agent phase —
4	// the executor runs `worker.mjs` as code-work. This task ABSORBS the
5	// release workflow's own independent 00:30 cron: the workflow becomes push +
6	// workflow_dispatch only, and this task is the one place that fires its daily
7	// leg, so the scheduler stays the repo's only cron (DESIGN §3, decision §11.6).
8	//
9	// Self-contained (imports nothing): the whole contract is this default export.
10	
11	const norm = (v) => String(v ?? '').replace(/^v/, '').trim(); // compare tags/versions modulo a leading 'v'
12	
13	export default {
14	  id: 'store-release',
15	  frequency: 'daily',              // the 04:00 anchor (DESIGN §2) — replaces the workflow's own 00:30 cron
16	  precondition_signals: ['release', 'commits'],
17	  agent_model: 'none',                   // pure code — no agent (task-code-work DESIGN §4)
18	  expected_outcome: 'none',                 // it only TRIGGERS the gated publish workflow; publishing stays behind that workflow's own guards
19	  code_work: 'node worker.mjs',      // the executor runs this as code_work (cwd = this task dir) — DESIGN §3
20	  code_work_timeout: 120,            // the dispatch is a quick REST call; a tight bound (the await-the-run Stage 2 would widen it)
21	
22	  // Detect a deployable change since the last release, entirely in code:
23	  //   (a) the manifest version has advanced past the latest published release
24	  //       (an unreleased bump — the same signal the old run_daily gate used), OR
25	  //   (b) a substantive default-branch commit landed in the window (a real ship).
26	  // Ship-path precision (the daily job's `ship_paths` filter) is NOT re-derived
27	  // here — .github/release.config isn't in a precondition's scope — because the
28	  // dispatched daily workflow does the authoritative shipped-file diff vs the
29	  // latest release tag and no-ops when nothing shippable moved. So the
30	  // precondition is the cheap pre-filter; the workflow is the exact gate.
31	  precondition(signals) {
32	    const rel = signals.release ?? {};
33	
34	    // Does this repo publish at all? The pack is fingerprinted on the manifest, so
35	    // it is active on every extension repo, including the ones that only code one —
36	    // and the daily leg this task fires is a workflow such a repo does not have.
37	    // `shipsPipeline` is the same orchestrator-name test the release checks gate on
38	    // (#1057); null means the collector could not read the checkout, which is not a
39	    // reason to fire a release.
40	    if (rel.shipsPipeline !== true) {
41	      return { run: false, reason: 'this repo does not ship the Chrome Web Store pipeline' };
42	    }
43	
44	    const shipped = norm(rel.manifestVersion);
45	    const released = norm(rel.latestTag);
46	    const manifestAhead = shipped !== '' && shipped !== released;
47	    const substantive = signals.commits?.substantiveChange === true;
48	
49	    if (manifestAhead) {
50	      return { run: true, reason: released ? `manifest ${shipped} is ahead of released ${released}` : `manifest ${shipped}, no release yet` };
51	    }
52	    if (substantive) {
53	      return { run: true, reason: 'substantive default-branch change in the window — let the daily release workflow diff shipped files' };
54	    }
55	    return { run: false, reason: 'manifest matches the latest release and no substantive change in the window' };
56	  },
57	};
